import { GoogleGenAI } from "@google/genai";

if (!process.env.API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const CUTS_PER_PAGE = 4;

const getMasterPrompt = (scriptChunk: string, includeText: boolean): string => {
    const textInstruction = includeText
        ? "4.  Text: DO NOT use speech balloons. Instead, write all dialogue, narration, and descriptive text directly on the image in a simple, legible, handwritten Korean font. It should look like the artist's own notes on the sketch."
        : "4.  Text: **CRITICAL INSTRUCTION: GENERATE A COMPLETELY SILENT PAGE. The image MUST NOT contain any text, letters, or narration. This is the most important rule. The final output must be purely visual. MANDATORY: NO TEXT.**";

    return `
**ABSOLUTE RULES: Your primary mission is to visualize the provided script with perfect accuracy using ONLY stick figures. DO NOT add any elements not mentioned in the script. The output MUST BE black and white monochrome. ABSOLUTELY NO COLOR.**

You are a storyboard artist creating a rough "name" (ネーム) or "conti" for a webtoon.
Your task is to create a SINGLE storyboard page based on the following script.

**STYLE RULES (MANDATORY):**
1.  **Characters:** Draw all characters as simple STICK FIGURES (졸라맨). Do not draw detailed characters. Use simple shapes like circles for heads and lines for bodies.
2.  **Format:** The page must be a vertical 9:16 aspect ratio, black and white sketch.
3.  **Layout:** **Crucial Rule:** Arrange all panels (cuts) in a simple vertical stack. Each panel must be a large, clear rectangle. Do not use complex layouts, slanted panels, or panels of varying widths. The final page should look like a standard webtoon with panels flowing from top to bottom.
${textInstruction}
5.  **Content:** You must follow the script exactly for panel descriptions, character actions, and dialogue.

**Script for this page:**
---
${scriptChunk}
---
`;
}


export const generateStickFigurePages = async (fullScript: string, includeText: boolean): Promise<string[]> => {
    if (!fullScript.trim()) {
        throw new Error("Script cannot be empty.");
    }

    const cuts = fullScript.trim().split(/\n(?=\d+\.\s)/).map(s => s.trim());
    if (cuts.length === 0) {
        throw new Error("Could not parse any cuts from the script.");
    }

    const pages: string[] = [];
    for (let i = 0; i < cuts.length; i += CUTS_PER_PAGE) {
        const pageCuts = cuts.slice(i, i + CUTS_PER_PAGE);
        pages.push(pageCuts.join('\n\n'));
    }

    const generatedImages: string[] = [];

    try {
        for (const pageScript of pages) {
            const prompt = getMasterPrompt(pageScript, includeText);

            const response = await ai.models.generateImages({
                model: 'imagen-4.0-generate-001',
                prompt: prompt,
                config: {
                    numberOfImages: 1,
                    outputMimeType: 'image/png',
                    aspectRatio: '9:16',
                },
            });

            if (response.generatedImages && response.generatedImages.length > 0) {
                const base64ImageBytes: string = response.generatedImages[0].image.imageBytes;
                generatedImages.push(base64ImageBytes);
            } else {
                console.error("Stick figure image generation failed for a page. API Response:", response);
                throw new Error(`Failed to generate a stick figure image for a page.`);
            }
        }
        return generatedImages;

    } catch (error) {
        console.error("Error generating stick figure storyboard:", error);
        if (error instanceof Error && error.message.includes('API_KEY')) {
            throw new Error("API Key is invalid or not configured correctly.");
        }
        throw new Error("졸라맨 콘티 생성 중 AI와 통신하는 데 실패했습니다.");
    }
};

