import { GoogleGenAI } from "@google/genai";

const CUTS_PER_PAGE = 4;

// Helper to clean up the script chunks
const chunkScript = (fullScript: string): string[] => {
  // Split by specific patterns like "1.", "1화", or double newlines if no numbers found
  // For robustness, we will try to split by numbered cuts first.
  const cuts = fullScript.split(/\n(?=\d+[\.\s])/g);

  if (cuts.length < 2) {
    // If regex didn't find multiple cuts, try splitting by double newlines
    const paragraphs = fullScript.split(/\n\s*\n/);
    const pages: string[] = [];
    let currentPage = "";
    let count = 0;

    for (const p of paragraphs) {
      if (!p.trim()) continue;
      currentPage += p + "\n\n";
      count++;
      if (count >= CUTS_PER_PAGE) {
        pages.push(currentPage.trim());
        currentPage = "";
        count = 0;
      }
    }
    if (currentPage.trim()) pages.push(currentPage.trim());
    return pages;
  }

  // Group identified cuts into pages
  const pages: string[] = [];
  let currentPageCuts: string[] = [];

  for (const cut of cuts) {
    if (!cut.trim()) continue;
    currentPageCuts.push(cut.trim());
    if (currentPageCuts.length >= CUTS_PER_PAGE) {
      pages.push(currentPageCuts.join('\n\n'));
      currentPageCuts = [];
    }
  }
  if (currentPageCuts.length > 0) {
    pages.push(currentPageCuts.join('\n\n'));
  }

  return pages;
};

export const generateStickFigurePage = async (scriptChunk: string, pageNumber: number): Promise<string> => {
  // IMPORTANT: Create a new instance here to ensure we use the latest API key selected by the user
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    You are a storyboard artist specializing in "Stick Figure" (Jolla-man) style rough drafts.

    **TASK**: Create a vertical storyboard page (aspect ratio 9:16) for the following script chunk.

    **STYLE GUIDELINES**:
    1. **Visual Style**: STICK FIGURES ONLY (졸라맨 스타일). Simple circles for heads, lines for bodies. Minimalist, rough sketch style. Black and white lines only.
    2. **Layout**: Draw exactly 4 panels stacked vertically.
    3. **Content**: Visualise the script below.
    4. **Text**: Do NOT add dialogue bubbles with text. Just draw the visual scene.

    **SCRIPT**:
    ${scriptChunk}
  `;

  try {
    const response = await ai.models.generateImages({
      model: 'imagen-4.0-generate-001',
      prompt: prompt,
      config: {
        numberOfImages: 1,
        outputMimeType: 'image/jpeg',
        aspectRatio: '9:16',
      },
    });

    if (response.generatedImages && response.generatedImages.length > 0) {
      return response.generatedImages[0].image.imageBytes;
    } else {
      throw new Error(`페이지 ${pageNumber} 생성 실패: 이미지가 반환되지 않았습니다.`);
    }
  } catch (error) {
    console.error(`Error generating page ${pageNumber}:`, error);
    throw error;
  }
};

