// Helper to split script into pages
const splitScriptToPages = (fullScript: string): string[] => {
    const cuts = fullScript.split(/\n(?=\d+[\.\s])/g).filter(c => c.trim().length > 0);
    if (cuts.length < 2) return fullScript.split(/\n\n+/).filter(c => c.trim().length > 0); // fallback

    const pages: string[] = [];
    const CUTS_PER_PAGE = 4;
    for (let i = 0; i < cuts.length; i += CUTS_PER_PAGE) {
        pages.push(cuts.slice(i, i + CUTS_PER_PAGE).join('\n\n'));
    }
    return pages;
};

interface StickFigureGeneratorProps {
    onBack: () => void;
}

export const StickFigureGenerator: React.FC<StickFigureGeneratorProps> = ({ onBack }) => {
    const [script, setScript] = useState('');
    const [generatedPages, setGeneratedPages] = useState<{ page: number; image: string }[]>([]);
    const [isLoading, setIsLoading] = useState(false);
    const [progress, setProgress] = useState('');
    const [error, setError] = useState<string | null>(null);

    const handleGenerate = async () => {
        if (!script.trim()) {
            setError('콘티 내용을 입력해주세요.');
            return;
        }

        setError(null);
        setIsLoading(true);
        setGeneratedPages([]);

        try {
            // 1. API Key Selection Logic (User pays!)
            const aiStudio = (window as any).aistudio;
            if (aiStudio) {
                const hasKey = await aiStudio.hasSelectedApiKey();
                if (!hasKey) {
                    await aiStudio.openSelectKey();
                    // Double check to handle race condition or cancellation
                    const checkAgain = await aiStudio.hasSelectedApiKey();
                    if (!checkAgain) {
                         throw new Error("API 키가 선택되지 않았습니다. 결제 가능한 프로젝트의 키를 선택해주세요.");
                    }
                }
            }

            // 2. Process Script
            const pages = splitScriptToPages(script);
            setProgress(`총 ${pages.length}페이지 생성을 시작합니다...`);

            for (let i = 0; i < pages.length; i++) {
                setProgress(`${i + 1} / ${pages.length} 페이지 생성 중... (졸라맨 그리는 중)`);
                try {
                    const base64Image = await generateStickFigurePage(pages[i], i + 1);
                    setGeneratedPages(prev => [...prev, { page: i + 1, image: base64Image }]);
                } catch (e) {
                    console.error(e);
                    // Continue generating other pages even if one fails
                    setError(`페이지 ${i + 1} 생성 중 오류가 발생했습니다.`);
                }
            }

            setProgress('완료!');

        } catch (err) {
            if (err instanceof Error) {
                // Check for standard Gemini API errors
                if (err.message.includes("Requested entity was not found") || err.message.includes("404")) {
                     setError("API 키 오류: 선택된 프로젝트에 문제가 있거나 권한이 없습니다. 다시 시도하여 유효한 유료 키를 선택해주세요.");
                     // Optional: trigger selection again
                     const aiStudio = (window as any).aistudio;
                     if (aiStudio) await aiStudio.openSelectKey();
                } else {
                    setError(err.message);
                }
            } else {
                setError('알 수 없는 오류가 발생했습니다.');
            }
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="w-full max-w-7xl mx-auto">
             <div className="mb-6">
                <button
                    onClick={onBack}
                    className="text-orange-600 hover:text-orange-800 transition-colors duration-200 flex items-center group text-sm"
                    aria-label="홈으로 돌아가기"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-2 transform group-hover:-translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                    </svg>
                    홈으로 돌아가기
                </button>
            </div>

            <div className="flex flex-col lg:flex-row gap-8">
                {/* Input Section */}
                <div className="lg:w-1/3 space-y-4">
                    <div className="bg-white p-6 rounded-xl shadow-lg border border-gray-200 h-full flex flex-col">
                        <h2 className="text-2xl font-bold text-gray-800 mb-2">졸라맨 콘티 생성기</h2>
                        <p className="text-sm text-gray-600 mb-4">
                            텍스트 콘티를 입력하면 AI가 심플한 졸라맨(Stick Figure) 스타일로 4컷 만화를 그려줍니다.
                        </p>

                        <textarea
                            className="flex-grow w-full bg-gray-50 border border-gray-300 rounded-md shadow-sm py-2 px-3 text-gray-900 focus:outline-none focus:ring-2 focus:ring-orange-500 transition placeholder-gray-400 min-h-[300px]"
                            placeholder={`[예시]
1. 강민우가 범인을 향해 달려간다.
2. 범인이 칼을 꺼내든다.
3. 강민우가 돌려차기로 칼을 떨어뜨린다.
4. 제압당하는 범인.`}
                            value={script}
                            onChange={(e) => setScript(e.target.value)}
                        />

                        <button
