import { GoogleGenAI } from "@google/genai";

const CUTS_PER_PAGE = 4;

// Helper to clean up the script chunks
const chunkScript = (fullScript: string): string[] => {
  // Split by specific patterns like "1.", "1화", or double newlines if no numbers found
  // For robustness, we will try to split by numbered cuts first.
  const cuts = fullScript.split(/\n(?=\d+[\.\s])/g);

  if (cuts.length < 2) {
    // If regex didn't find multiple cuts, try splitting by double newlines
    const paragraphs = fullScript.split(/\n\s*\n/);
    const pages: string[] = [];
    let currentPage = "";
    let count = 0;

    for (const p of paragraphs) {
      if (!p.trim()) continue;
      currentPage += p + "\n\n";
      count++;
      if (count >= CUTS_PER_PAGE) {
        pages.push(currentPage.trim());
        currentPage = "";
        count = 0;
      }
    }
    if (currentPage.trim()) pages.push(currentPage.trim());
    return pages;
  }

  // Group identified cuts into pages
  const pages: string[] = [];
  let currentPageCuts: string[] = [];

  for (const cut of cuts) {
    if (!cut.trim()) continue;
    currentPageCuts.push(cut.trim());
    if (currentPageCuts.length >= CUTS_PER_PAGE) {
      pages.push(currentPageCuts.join('\n\n'));
      currentPageCuts = [];
    }
  }
  if (currentPageCuts.length > 0) {
    pages.push(currentPageCuts.join('\n\n'));
  }

  return pages;
};

export const generateStickFigurePage = async (scriptChunk: string, pageNumber: number): Promise<string> => {
  // IMPORTANT: Create a new instance here to ensure we use the latest API key selected by the user
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const prompt = `
    You are a professional storyboard artist specializing in "Stick Figure" (Jolla-man) style rough drafts for webtoons.

    **TASK**: Create a vertical storyboard page (aspect ratio 9:16) for the following script chunk.

    **LAYOUT REQUIREMENTS (CONSISTENCY IS KEY)**:
    1.  **Structure**: Divide the vertical page into exactly 4 equal sections.
    2.  **Panels**: In each section, draw a rectangular frame (aspect ratio approx 16:9).
    3.  **Captions (MANDATORY)**: **Directly BELOW each panel frame, write the exact Korean script text** corresponding to that scene.
    4.  **Consistency**: Ensure all 4 panels are aligned and have the same width.

    **VISUAL STYLE**:
    -   **Art Style**: Stick Figures (Jolla-man) only. Simple circles for heads, lines for bodies.
    -   **Medium**: Black and white sketch / line art.
    -   **Atmosphere**: Clear and rough continuity sketch.

    **SCRIPT TO VISUALIZE**:
    ${scriptChunk}
  `;

  try {
    // Use gemini-3-pro-image-preview (Nano Banana Pro)
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: [{ text: prompt }],
      },
      config: {
        imageConfig: {
          aspectRatio: '9:16',
          imageSize: '1K',
        },
      },
    });

    let imageBase64: string | undefined;

    if (response.candidates && response.candidates.length > 0 && response.candidates[0].content && response.candidates[0].content.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageBase64 = part.inlineData.data;
          break;
        }
      }
    }

    if (imageBase64) {
      return imageBase64;
    } else {
      throw new Error(`페이지 ${pageNumber} 생성 실패: 이미지가 반환되지 않았습니다.`);
    }
  } catch (error) {
    console.error(`Error generating page ${pageNumber}:`, error);
    throw error;
  }
};

