import { GoogleGenAI } from "@google/genai";
import { CharacterReference } from '../types';

// Helper to construct the strict reference prompt
const getReferencePromptFragment = (references: CharacterReference[]): string => {
  if (references.length === 0) return "";

  let prompt = `\n\n### CRITICAL CHARACTER REFERENCES (MANDATORY)\n`;
  prompt += `I have provided reference images for the characters below. You MUST IGNORE any conflicting internal knowledge and follow these images exactly for:\n`;
  prompt += `- Hairstyle and Color\n- Face Shape and Features\n- Eye Shape and Color\n- Body Type\n\n`;

  references.forEach(ref => {
    prompt += `- **${ref.name}**: See the image labeled [Reference for ${ref.name}]. Draw this exact person.\n`;
  });

  return prompt;
};

// 1. Generate Single Panel (Webtoon Cut)
export const generateWebtoonPanel = async (
  cutId: string,
  sceneDescription: string,
  directing: string,
  charactersInCut: string,
  references: CharacterReference[]
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Pass ALL references to ensure the model sees them. 
  // Filtering by name is error-prone if the script uses variations (Minwoo vs Kang Minwoo).
  // The model is smart enough to pick the right one based on the 'charactersInCut' context.

  const parts: any[] = [];

  let promptText = `
    **ROLE**: Professional Webtoon Artist.
    **TASK**: Draw a single high-quality webtoon panel (1 cut) for the scene described below.

    **VISUAL STYLE**: 
    - High-quality Korean Webtoon style (Manhwa).
    - Anime-influenced semi-realistic characters.
    - Cinematic lighting and composition.
    - Full color.

    **SCENE INFO**:
    - **Context**: ${sceneDescription}
    - **Characters Present**: ${charactersInCut}
    - **Directing**: ${directing}
  `;

  // Add Reference Instructions
  promptText += getReferencePromptFragment(references);

  parts.push({ text: promptText });

  // Append Reference Images with clear labels
  references.forEach(ref => {
      parts.push({ text: `[Reference for ${ref.name}]` });
      parts.push({
          inlineData: {
              data: ref.imageBase64,
              mimeType: ref.mimeType
          }
      });
  });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: '4:3', // Wide/Standard panel for single cut
          imageSize: '1K',
        },
      },
    });

    let imageBase64: string | undefined;
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageBase64 = part.inlineData.data;
          break;
        }
      }
    }

    if (imageBase64) return imageBase64;
    throw new Error(`이미지 생성 실패: 모델이 이미지를 반환하지 않았습니다.`);
  } catch (error) {
    console.error(`Error generating webtoon panel for cut ${cutId}:`, error);
    throw error;
  }
};

// 2. Generate Full Page (Manga Page Layout)
export const generateWebtoonPage = async (
  pageId: number,
  cuts: { cut: string; recommendation: string; characters: string }[],
  references: CharacterReference[]
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts: any[] = [];

  let promptText = `
    **ROLE**: Professional Manga/Webtoon Artist.
    **TASK**: Draw a **Single Manga Page** containing exactly ${cuts.length} panels (cuts) laid out dynamically.

    **LAYOUT**: 
    - Create a vertical page layout (comic book style).
    - Arrange ${cuts.length} panels on this page.
    - Ensure clear separation (gutters) between panels.

    **CONTENT**:
  `;

  cuts.forEach((cut, index) => {
    promptText += `
    [Panel ${index + 1} (Cut ${cut.cut})]
    - Scene: ${cut.recommendation}
    - Characters: ${cut.characters}
    `;
  });

  promptText += getReferencePromptFragment(references);

  parts.push({ text: promptText });

  references.forEach(ref => {
      parts.push({ text: `[Reference for ${ref.name}]` });
      parts.push({
          inlineData: {
              data: ref.imageBase64,
              mimeType: ref.mimeType
          }
      });
  });

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: '3:4', // Vertical Page Format
          imageSize: '1K',
        },
      },
    });

    let imageBase64: string | undefined;
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageBase64 = part.inlineData.data;
          break;
        }
      }
    }

    if (imageBase64) return imageBase64;
    throw new Error(`페이지 생성 실패: 모델이 이미지를 반환하지 않았습니다.`);
  } catch (error) {
    console.error(`Error generating webtoon page ${pageId}:`, error);
    throw error;
  }
};

