import { GoogleGenAI } from "@google/genai";
import { CharacterReference, BackgroundReference, WebtoonGenerationOptions } from '../types';

// Helper to construct the strict reference prompt
const getReferencePromptFragment = (references: CharacterReference[]): string => {
  if (references.length === 0) return "";

  let prompt = `\n\n### CRITICAL CHARACTER REFERENCES (MANDATORY)\n`;
  prompt += `I have provided reference images for the characters below. You MUST IGNORE any conflicting internal knowledge and follow these images exactly for:\n`;
  prompt += `- Hairstyle and Color\n- Face Shape and Features\n- Eye Shape and Color\n- Body Type\n\n`;

  references.forEach(ref => {
    prompt += `- **${ref.name}**: See the image labeled [Reference for ${ref.name}]. Draw this exact person.\n`;
  });

  return prompt;
};

// 1. Generate Single Panel (Webtoon Cut)
export const generateWebtoonPanel = async (
  cutId: string,
  sceneDescription: string,
  directing: string,
  charactersInCut: string,
  references: CharacterReference[],
  options: WebtoonGenerationOptions,
  backgroundRef?: BackgroundReference | null
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts: any[] = [];

  const styleInstruction = options.isColor
    ? "**VISUAL STYLE**: High-quality Full Color Webtoon (Manhwa). Vibrant colors, cinematic lighting, 3D-like depth."
    : "**VISUAL STYLE**: Black and White Manga/Comics style. High contrast, clean ink lines, screen tones (screentone). NO COLOR.";

  const bubbleInstruction = options.hasSpeechBubbles
    ? "**SPEECH BALLOONS**: MANDATORY. Include dialogue bubbles where appropriate for the characters speaking. Use vertical text layout for speech if possible."
    : "**SPEECH BALLOONS**: ABSOLUTELY FORBIDDEN. Do not draw any speech bubbles, text, or sound effects. Pure illustration only.";

  const bgInstruction = backgroundRef
    ? `**BACKGROUND**: Use the provided [Background Reference] image. You MUST match the architectural style, lighting, and atmosphere of this reference exactly.`
    : ``;

  let promptText = `
    **ROLE**: Professional Webtoon/Manga Artist.
    **TASK**: Draw a single panel (1 cut) for the scene described below.

    **STRICT SCRIPT ADHERENCE**:
    - You MUST draw EXACTLY what is described in the "Context" and "Action".
    - Focus on the specific action: "${sceneDescription}".
    - If the script says a character is doing X, they MUST be doing X.

    ${styleInstruction}
    ${bubbleInstruction}

    **SCENE INFO**:
    - **Context/Action**: ${sceneDescription}
    - **Characters Present**: ${charactersInCut}
    - **Directing**: ${directing}
    ${bgInstruction}
  `;

  // Add Character Reference Instructions
  promptText += getReferencePromptFragment(references);

  parts.push({ text: promptText });

  // Append Character Reference Images
  references.forEach(ref => {
      parts.push({ text: `[Reference for ${ref.name}]` });
      parts.push({
          inlineData: {
              data: ref.imageBase64,
              mimeType: ref.mimeType
          }
      });
  });

  // Append Background Reference Image
  if (backgroundRef) {
      parts.push({ text: `[Background Reference]` });
      parts.push({
          inlineData: {
              data: backgroundRef.imageBase64,
              mimeType: backgroundRef.mimeType
          }
      });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: '4:3',
          imageSize: '1K',
        },
      },
    });

    let imageBase64: string | undefined;
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageBase64 = part.inlineData.data;
          break;
        }
      }
    }

    if (imageBase64) return imageBase64;
    throw new Error(`이미지 생성 실패: 모델이 이미지를 반환하지 않았습니다.`);
  } catch (error) {
    console.error(`Error generating webtoon panel for cut ${cutId}:`, error);
    throw error;
  }
};

// 2. Generate Full Page (Manga Page Layout)
export const generateWebtoonPage = async (
  pageId: number,
  cuts: { cut: string; recommendation: string; characters: string }[],
  references: CharacterReference[],
  options: WebtoonGenerationOptions,
  backgroundRef?: BackgroundReference | null
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts: any[] = [];

  const styleInstruction = options.isColor
    ? "**VISUAL STYLE**: High-quality Full Color Webtoon. Vertical scroll layout preferred."
    : "**VISUAL STYLE**: Black and White Manga Page. Traditional comic book layout with gutters. Screen tones.";

  const bubbleInstruction = options.hasSpeechBubbles
    ? "**SPEECH BALLOONS**: MANDATORY. Include dialogue bubbles."
    : "**SPEECH BALLOONS**: NO TEXT. NO BUBBLES.";

   const bgInstruction = backgroundRef
    ? `**BACKGROUND**: Use the provided [Background Reference] image for the setting.`
    : ``;

  let promptText = `
    **ROLE**: Professional Manga/Webtoon Artist.
    **TASK**: Draw a **Single Manga Page** containing exactly ${cuts.length} panels (cuts).

    **STRICT SCRIPT ADHERENCE**:
    - Draw exactly the scenes described below in order.

    ${styleInstruction}
    ${bubbleInstruction}

    **CONTENT**:
  `;

  cuts.forEach((cut, index) => {
    promptText += `
