// Drag and Drop Helper
const DragDropZone: React.FC<{
    label: string;
    subLabel: string;
    onFileDrop: (file: File) => void;
    children?: React.ReactNode;
}> = ({ label, subLabel, onFileDrop, children }) => {
    const [isDragOver, setIsDragOver] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragOver(true);
    };
    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragOver(false);
    };
    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragOver(false);
        const file = e.dataTransfer.files[0];
        if (file && file.type.startsWith('image/')) {
            onFileDrop(file);
        }
    };
    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            onFileDrop(file);
            // Reset value so same file can be selected again
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };

    return (
        <div
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            className={`border-2 border-dashed rounded-xl p-6 text-center transition-colors cursor-pointer relative ${
                isDragOver ? 'border-indigo-500 bg-indigo-50' : 'border-gray-300 hover:border-indigo-400 bg-gray-50'
            }`}
        >
             <input
                type="file"
                ref={fileInputRef}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                accept="image/*"
                onChange={handleChange}
            />
            <div className="pointer-events-none">
                <p className="font-bold text-gray-700">{label}</p>
                <p className="text-sm text-gray-500 mt-1">{subLabel}</p>
                {children}
            </div>
        </div>
    );
};


export const StoryAnalyzer: React.FC<StoryAnalyzerProps> = ({ onBack }) => {
    const [storyText, setStoryText] = useState('');
    const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [backgroundViewMode, setBackgroundViewMode] = useState('list');
    const [outfitViewMode, setOutfitViewMode] = useState('list');

    // Webtoon Generation State
    const [charRefs, setCharRefs] = useState<CharacterReference[]>([]);
    const [bgRef, setBgRef] = useState<BackgroundReference | null>(null);
    const [refNameInput, setRefNameInput] = useState('');

    // Options
    const [isColor, setIsColor] = useState<boolean>(true);
    const [hasSpeechBubbles, setHasSpeechBubbles] = useState<boolean>(true);

    const [isGenerating, setIsGenerating] = useState(false);
    const [generationMode, setGenerationMode] = useState<'single' | 'page'>('single');
    const [generatedPanels, setGeneratedPanels] = useState<{ [cutId: string]: string }>({});
    const [generatedPages, setGeneratedPages] = useState<{ id: number, cuts: string[], image: string }[]>([]);
    const [generationProgress, setGenerationProgress] = useState('');

    const backgroundsByEpisode = useMemo(() => {
        if (!analysis?.backgrounds) return {};
        const grouped: { [key: string]: AnalysisResult['backgrounds'] } = {};
        analysis.backgrounds.forEach(bg => {
            const match = bg.description.match(/(\d+)(?:화)?/);
            const episodeKey = match ? `${match[1]}화` : '기타';
            if (!grouped[episodeKey]) grouped[episodeKey] = [];
            grouped[episodeKey].push(bg);
        });
        return grouped;
    }, [analysis]);

    const outfitsByEpisode = useMemo(() => {
        if (!analysis?.outfits) return {};
        return analysis.outfits.reduce((acc, outfit) => {
            const episodeKey = outfit.episode.match(/\d+/) ? `${outfit.episode.match(/\d+/)[0]}화` : '기타';
            if (!acc[episodeKey]) acc[episodeKey] = [];
            acc[episodeKey].push(outfit);
            return acc;
        }, {} as { [key: string]: AnalysisResult['outfits'] });
    }, [analysis]);


    const handleAnalyze = useCallback(async () => {
        const inputText = storyText.trim();
        if (!inputText) {
            setError('분석할 스토리 내용이나 Google Docs 링크를 입력해주세요.');
            return;
        }

        setIsLoading(true);
        setError(null);
        setAnalysis(null);

        let contentToAnalyze = inputText;

        const googleDocsRegex = /https:\/\/docs\.google\.com\/document\/d\/([a-zA-Z0-9-_]+)/;
        const match = inputText.match(googleDocsRegex);

        if (match) {
            const docId = match[1];
            // Use the more reliable text export URL instead of scraping the preview page
            const docUrl = `https://docs.google.com/document/d/${docId}/export?format=txt`;
            const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(docUrl)}`;

            try {
                const response = await fetch(proxyUrl);
                if (!response.ok) throw new Error(`CORS proxy failed with status: ${response.status}`);

                // The response is now plain text, no HTML parsing needed
                const extractedText = await response.text();

                if (!extractedText || extractedText.trim().length < 10) {
                     throw new Error('문서 내용을 추출하지 못했습니다. 문서가 비어있거나 공개 상태가 아닐 수 있습니다.');
                }
                contentToAnalyze = extractedText;
            } catch (err) {
                console.error(err);
                setError('오류: 문서를 읽을 수 없습니다. 제공된 Google Docs 링크에 접근할 수 없거나, 문서의 권한이 \'링크가 있는 모든 사용자\'로 설정되지 않았을 수 있습니다.');
                setIsLoading(false);
                return;
            }
        }

        try {
            const result = await analyzeStory(contentToAnalyze);
            setAnalysis(result);
        } catch (err) {
            setError(err instanceof Error ? err.message : '스토리 분석 중 알 수 없는 오류가 발생했습니다.');
        } finally {
            setIsLoading(false);
        }
    }, [storyText]);

    const processFile = (file: File): Promise<{ base64: string, mimeType: string }> => {
        return new Promise((resolve) => {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64String = reader.result as string;
                const base64Data = base64String.split(',')[1];
                resolve({ base64: base64Data, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        });
    };

    const handleCharRefDrop = async (file: File) => {
        if (!refNameInput.trim()) {
            alert('캐릭터 이름을 먼저 입력해주세요.');
            return;
        }
        const { base64, mimeType } = await processFile(file);
        const newRef: CharacterReference = {
            id: Date.now().toString(),
            name: refNameInput.trim(),
            imageBase64: base64,
            mimeType: mimeType
        };
        setCharRefs(prev => [...prev, newRef]);
        setRefNameInput('');
    };

    const handleBgRefDrop = async (file: File) => {
        const { base64, mimeType } = await processFile(file);
        setBgRef({
            id: Date.now().toString(),
            name: "Background Reference",
            imageBase64: base64,
            mimeType: mimeType
        });
    };

    const removeReference = (id: string) => {
        setCharRefs(charRefs.filter(r => r.id !== id));
    };

    const handleGenerateWebtoon = async () => {
        if (!analysis || !analysis.directingRecommendations || analysis.directingRecommendations.length === 0) {
            setError('생성할 컷 정보가 없습니다. 스토리를 먼저 분석해주세요 (컷 구분이 명확해야 합니다).');
            return;
        }

        setIsGenerating(true);
        setGenerationProgress('API 키 확인 중...');
        setError(null);
        setGeneratedPages([]); // clear previous pages if switching
        // Don't clear single panels if we switch, just keep them in state

        const options = {
            isColor,
            hasSpeechBubbles
        };

        try {
             // API Key Selection Check
            const aiStudio = (window as any).aistudio;
            if (aiStudio) {
                const hasKey = await aiStudio.hasSelectedApiKey();
                if (!hasKey) {
                    await aiStudio.openSelectKey();
                    const checkAgain = await aiStudio.hasSelectedApiKey();
                    if (!checkAgain) throw new Error("API 키가 선택되지 않았습니다.");
                }
            }

            const recommendations = analysis.directingRecommendations as any[];

            if (generationMode === 'single') {
                // --- SINGLE CUT MODE ---
                let completed = 0;
                for (const item of recommendations) {
                    if (generatedPanels[item.cut]) { completed++; continue; }

                    setGenerationProgress(`컷 ${item.cut} 생성 중... (${completed + 1}/${recommendations.length})`);

                    const cutInfo = (analysis.charactersByCut as any[])?.find((c: any) => c.cut === item.cut);
                    const charactersInCut = cutInfo ? cutInfo.characters : "Unknown";

                    try {
                        const image = await generateWebtoonPanel(
                            item.cut,
                            item.recommendation,
                            item.recommendation,
                            charactersInCut,
                            charRefs, // Pass ALL references, let service handle prompt instruction
                            options,
                            bgRef
                        );
                        setGeneratedPanels(prev => ({ ...prev, [item.cut]: image }));
                    } catch (err) {
                        console.error(`Failed to generate cut ${item.cut}`, err);
                    }
                    completed++;
                }
            } else {
                // --- PAGE MODE ---
                const CUTS_PER_PAGE = 4; // Adjust as needed
                const pages = [];
                for (let i = 0; i < recommendations.length; i += CUTS_PER_PAGE) {
                    pages.push(recommendations.slice(i, i + CUTS_PER_PAGE));
                }

                for (let i = 0; i < pages.length; i++) {
                    setGenerationProgress(`페이지 ${i + 1} 생성 중... (${i + 1}/${pages.length})`);

                    const pageCuts = pages[i].map((rec: any) => {
                        const cutInfo = (analysis.charactersByCut as any[])?.find((c: any) => c.cut === rec.cut);
                        return {
                            cut: rec.cut,
                            recommendation: rec.recommendation,
                            characters: cutInfo ? cutInfo.characters : "Unknown"
                        };
                    });

                    try {
                        const image = await generateWebtoonPage(i + 1, pageCuts, charRefs, options, bgRef);
                        setGeneratedPages(prev => [...prev, { 
                            id: i + 1, 
                            cuts: pageCuts.map((p: any) => p.cut), 
                            image 
                        }]);
                    } catch (err) {
                        console.error(`Failed to generate page ${i + 1}`, err);
                    }
                }
            }

            setGenerationProgress('생성이 완료되었습니다.');

        } catch (err) {
             setError(err instanceof Error ? err.message : '웹툰 생성 중 오류가 발생했습니다.');
        } finally {
            setIsGenerating(false);
        }
    };

    return (
        <div className="w-full max-w-4xl mx-auto">
            <div className="mb-6">
                <button
                    onClick={onBack}
                    className="text-emerald-600 hover:text-emerald-800 transition-colors duration-200 flex items-center group text-sm"
                    aria-label="홈으로 돌아가기"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-2 transform group-hover:-translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                    </svg>
                    홈으로 돌아가기
                </button>
            </div>

            {/* Analysis Input Section */}
            <div className="bg-white p-6 md:p-8 rounded-xl shadow-lg border border-gray-200 space-y-6">
                 <div className="text-center">
                    <h2 className="text-3xl font-bold text-gray-900">AI 스토리 분석기</h2>
                    <p className="text-gray-600 mt-2">웹툰 스토리 전체를 붙여넣거나 Google Docs 링크를 입력하면 AI가 등장인물, 배경, 복장, 그리고 각 컷의 연출까지 체계적으로 분석해 드립니다.</p>
                </div>

                <div>
                     <label htmlFor="story-input" className="block text-sm font-medium text-gray-600 mb-2">
                        스토리 전체 내용 또는 Google Docs 링크
                    </label>
                    <textarea
                        id="story-input"
                        rows={10}
                        className="w-full bg-gray-50 border border-gray-300 rounded-md shadow-sm py-2 px-3 text-gray-900 focus:outline-none focus:ring-2 focus:ring-emerald-500 transition placeholder-gray-400"
                        placeholder="구글 문서 링크를 붙여넣으세요 (주의 : 권한을 '링크가 있는 모든 사용자'로 바꿔주세요)"
                        value={storyText}
                        onChange={(e) => setStoryText(e.target.value)}
                    />
                </div>

                <button
                    onClick={handleAnalyze}
                    disabled={isLoading}
                    className="w-full flex justify-center items-center bg-emerald-600 hover:bg-emerald-700 disabled:bg-emerald-500/50 disabled:cursor-not-allowed text-white font-bold py-3 px-4 rounded-md shadow-lg transition-all duration-300 ease-in-out transform hover:scale-105"
                >
                    {isLoading ? '분석 중...' : '스토리 분석하기'}
                </button>
            </div>

            {error && <div className="mt-6"><ErrorMessage message={error} /></div>}

            <div className="mt-12">
                {isLoading && !analysis && <LoadingSpinner />}
                {analysis && (
                    <div className="space-y-6 animate-fade-in">
                        {/* Existing Analysis Results */}
                        <Accordion title="전체 등장인물" defaultOpen={true} copyContent={analysis.allCharacters}>
                           <div className="flex flex-wrap gap-2">
                                {analysis.allCharacters.split(',').map(name => name.trim()).filter(Boolean).map((name, index) => (
