import { GoogleGenAI } from "@google/genai";
import { CharacterReference, BackgroundReference, WebtoonGenerationOptions } from '../types';

// Helper to construct the strict reference prompt
const getReferencePromptFragment = (references: CharacterReference[]): string => {
  if (references.length === 0) return "";

  let prompt = `\n\n### 🛑 CRITICAL INSTRUCTION: CHARACTER REFERENCES\n`;
  prompt += `You have been provided with reference images for the characters. \n`;
  prompt += `**YOU MUST CLONE THE FACE FROM THE REFERENCE IMAGE.**\n`;
  prompt += `Do not "reinterpret" the character. Do not "stylize" the face differently. \n`;
  prompt += `If the reference shows a specific hairstyle, eye shape, or jawline, YOU MUST DRAW IT EXACTLY THE SAME.\n\n`;

  references.forEach(ref => {
    prompt += `- **${ref.name}**: Use the image labeled [Reference for ${ref.name}]. Copy this person's facial features exactly.\n`;
  });

  return prompt;
};

const getRatioInstruction = (ratio: '2' | '5' | '8'): string => {
  switch (ratio) {
    case '2':
      return "**BODY PROPORTIONS**: 2-head tall 'Chibi' style (SD characters). Cute, big head, small body, super deformed.";
    case '5':
      return "**BODY PROPORTIONS**: 5-head tall 'Semi-deformed' style. Standard Webtoon/Anime casual proportions. Not too realistic, not too chibi.";
    case '8':
      return "**BODY PROPORTIONS**: 8-head tall proportions. Natural anatomy, balanced body ratios. Not photo-realistic, but anatomically correct.";
    default:
      return "**BODY PROPORTIONS**: 5-head tall 'Semi-deformed' style.";
  }
};

// 1. Generate Single Panel (Webtoon Cut)
export const generateWebtoonPanel = async (
  cutId: string,
  sceneDescription: string,
  directing: string,
  charactersInCut: string,
  references: CharacterReference[],
  options: WebtoonGenerationOptions,
  backgroundRef?: BackgroundReference | null
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts: any[] = [];

  const styleInstruction = options.isColor
    ? "**VISUAL STYLE**: High-quality Full Color Webtoon (Manhwa). Vibrant colors. No grayscale."
    : "**VISUAL STYLE**: Black and White Manga/Comics style. High contrast ink lines, screentones. NO COLOR.";

  const bubbleInstruction = options.hasSpeechBubbles
    ? "**SPEECH BALLOONS**: YES. The character IS SPEAKING. Draw a speech bubble. (Text inside can be gibberish, but the bubble must exist)."
    : "**SPEECH BALLOONS**: NO. Do not draw any speech bubbles.";

  const ratioInstruction = getRatioInstruction(options.ratio);

  const bgInstruction = backgroundRef
    ? `**BACKGROUND**: Use the provided [Background Reference] image. Match the perspective and architecture EXACTLY.`
    : ``;

  // Constructing a very aggressive system prompt
  let promptText = `
    **ROLE**: You are a mechanical photocopier/renderer. You are NOT a creative writer.
    **TASK**: Visualize the scene described below exactly as written.

    ### 🛑 STRICT ADHERENCE RULES (DO NOT IGNORE)
    1. **NO ADAPTATION**: Do not change the scene. Do not "improve" the acting. If the description says "Serious face", draw a serious face. If it says "Shouting", draw shouting.
    2. **DIALOGUE CONTEXT**: The characters are saying specific lines. Use the scene description to understand their EXACT emotion.
    3. **VISUAL STYLE**: ${styleInstruction}
    4. **SPEECH BUBBLES**: ${bubbleInstruction}
    5. **PROPORTIONS**: ${ratioInstruction}

    ### SCENE DATA
    - **Characters**: ${charactersInCut}
    - **Action/Context**: ${sceneDescription}
    - **Visual Direction**: ${directing}
    ${bgInstruction}
  `;

  // Add Reference Instructions
  promptText += getReferencePromptFragment(references);

  parts.push({ text: promptText });

  // Append Character Reference Images (Interleaved for better attention)
  references.forEach(ref => {
      parts.push({ text: `[Reference for ${ref.name}]` });
      parts.push({
          inlineData: {
              data: ref.imageBase64,
              mimeType: ref.mimeType
          }
      });
  });

  // Append Background Reference Image
  if (backgroundRef) {
      parts.push({ text: `[Background Reference]` });
      parts.push({
          inlineData: {
              data: backgroundRef.imageBase64,
              mimeType: backgroundRef.mimeType
          }
      });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: '4:3',
          imageSize: '1K',
        },
      },
    });

    let imageBase64: string | undefined;
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageBase64 = part.inlineData.data;
          break;
        }
      }
    }

    if (imageBase64) return imageBase64;
    throw new Error(`이미지 생성 실패: 모델이 이미지를 반환하지 않았습니다.`);
  } catch (error) {
    console.error(`Error generating webtoon panel for cut ${cutId}:`, error);
    throw error;
  }
};

// 2. Generate Full Page (Manga Page Layout)
export const generateWebtoonPage = async (
  pageId: number,
  cuts: { cut: string; recommendation: string; characters: string }[],
  references: CharacterReference[],
  options: WebtoonGenerationOptions,
  backgroundRef?: BackgroundReference | null
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts: any[] = [];

  const styleInstruction = options.isColor
    ? "**VISUAL STYLE**: Full Color Webtoon format."
    : "**VISUAL STYLE**: Black and White Manga format. Screen tones.";

  const bubbleInstruction = options.hasSpeechBubbles
    ? "**SPEECH BALLOONS**: YES. Mandatory."
    : "**SPEECH BALLOONS**: NO. Forbidden.";

  const ratioInstruction = getRatioInstruction(options.ratio);

   const bgInstruction = backgroundRef
    ? `**BACKGROUND**: Use the provided [Background Reference] image.`
    : ``;

  let promptText = `
    **ROLE**: Manga Artist.
    **TASK**: Draw a Single Page with ${cuts.length} panels.

    ### 🛑 STRICT ADHERENCE RULES
    - Draw exactly what is in the description.
    - Follow the character references EXACTLY.
    - **PROPORTIONS**: ${ratioInstruction}

    ${styleInstruction}
    ${bubbleInstruction}

    ### PANELS
  `;

  cuts.forEach((cut, index) => {
    promptText += `
    [Panel ${index + 1} (Cut ${cut.cut})]
    - Action: ${cut.recommendation}
    - Characters: ${cut.characters}
    `;
  });

  promptText += `\n${bgInstruction}`;
  promptText += getReferencePromptFragment(references);

  parts.push({ text: promptText });

  references.forEach(ref => {
      parts.push({ text: `[Reference for ${ref.name}]` });
      parts.push({
          inlineData: {
              data: ref.imageBase64,
              mimeType: ref.mimeType
          }
      });
  });

   if (backgroundRef) {
      parts.push({ text: `[Background Reference]` });
      parts.push({
          inlineData: {
              data: backgroundRef.imageBase64,
              mimeType: backgroundRef.mimeType
          }
      });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: '3:4', // Vertical Page Format
          imageSize: '1K',
        },
      },
    });

    let imageBase64: string | undefined;
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageBase64 = part.inlineData.data;
          break;
        }
      }
    }

    if (imageBase64) return imageBase64;
    throw new Error(`페이지 생성 실패: 모델이 이미지를 반환하지 않았습니다.`);
  } catch (error) {
    console.error(`Error generating webtoon page ${pageId}:`, error);
    throw error;
  }
};

