// Helper to construct the strict reference prompt
const getReferencePromptFragment = (references: CharacterReference[]): string => {
  if (references.length === 0) return "";

  let prompt = `\n\n### 🛑 CRITICAL INSTRUCTION: CHARACTER APPEARANCE PRIORITY\n`;
  prompt += `Reference images have been provided at the top of this prompt. \n`;
  prompt += `**YOU MUST PRIORITIZE THE REFERENCE IMAGES OVER ANY TEXT DESCRIPTION.**\n`;
  prompt += `1. **VISUAL CLONING**: Copy the hairstyle, hair color, eye shape, and accessories EXACTLY from the reference image.\n`;
  prompt += `2. **IGNORE CONTRADICTIONS**: If the scene description says "long hair" but the reference image shows "short hair", DRAW SHORT HAIR.\n`;
  prompt += `3. **COLOR & OUTFIT**: Use the exact colors and clothing style visible in the reference image unless explicitly told the character changed clothes.\n\n`;

  references.forEach(ref => {
    prompt += `- **${ref.name}**: Look at [Reference for ${ref.name}] above. That is exactly how ${ref.name} looks.\n`;
  });

  return prompt;
};

const getRatioInstruction = (ratio: '2' | '5' | '8'): string => {
  switch (ratio) {
    case '2':
      return "**BODY PROPORTIONS**: 2-head tall 'Chibi' style (SD characters). Cute, big head, small body, super deformed.";
    case '5':
      return "**BODY PROPORTIONS**: 5-head tall 'Semi-deformed' style. Standard Webtoon/Anime casual proportions. Not too realistic, not too chibi.";
    case '8':
      return "**BODY PROPORTIONS**: 8-head tall proportions. Natural anatomy, balanced body ratios. Not photo-realistic, but anatomically correct.";
    default:
      return "**BODY PROPORTIONS**: 5-head tall 'Semi-deformed' style.";
  }
};

