const Accordion: React.FC<{ title: string; children: React.ReactNode; defaultOpen?: boolean; copyContent?: string | null; }> = ({ title, children, defaultOpen = false, copyContent }) => {
    const [isOpen, setIsOpen] = useState(defaultOpen);
    const [isCopied, setIsCopied] = useState(false);

    const handleCopy = (e: React.MouseEvent) => {
        e.stopPropagation(); // Prevent accordion from toggling
        if (!copyContent) return;
        navigator.clipboard.writeText(copyContent);
        setIsCopied(true);
        setTimeout(() => setIsCopied(false), 2000);
    };

    return (
        <div className="bg-white rounded-xl border border-gray-200 shadow-lg">
            <div
                onClick={() => setIsOpen(!isOpen)}
                className="w-full flex justify-between items-center p-5 text-left cursor-pointer"
                aria-expanded={isOpen}
            >
                <h3 className="text-xl font-bold text-emerald-600">{title}</h3>
                <div className="flex items-center space-x-4">
                     {copyContent && (
                        <button
                            onClick={handleCopy}
                            className={`text-sm font-semibold py-1 px-3 rounded-md transition-colors ${isCopied ? 'bg-green-600 text-white' : 'bg-gray-200 text-gray-700 hover:bg-gray-300'}`}
                            aria-label={`Copy ${title}`}
                        >
                            {isCopied ? '복사됨!' : '복사'}
                        </button>
                    )}
                    <svg
                        xmlns="http://www.w3.org/2000/svg"
                        className={`h-6 w-6 transform transition-transform duration-300 ${isOpen ? 'rotate-180' : ''}`}
                        fill="none"
                        viewBox="0 0 24 24"
                        stroke="currentColor"
                    >
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                    </svg>
                </div>
            </div>
            {isOpen && (
                <div className="p-5 border-t border-gray-200">
                    <div className="prose max-w-none text-gray-700">{children}</div>
                </div>
            )}
        </div>
    );
};

const ViewToggleButton: React.FC<{ viewMode: string; setViewMode: (mode: string) => void; modes: { value: string; label: string }[] }> = ({ viewMode, setViewMode, modes }) => (
    <div className="flex bg-gray-200 rounded-lg p-1">
        {modes.map(mode => (
            <button
                key={mode.value}
                onClick={() => setViewMode(mode.value)}
                className={`w-full text-sm font-semibold py-1 px-3 rounded-md transition-colors ${viewMode === mode.value ? 'bg-emerald-600 text-white' : 'text-gray-700 hover:bg-gray-300'}`}
            >
                {mode.label}
            </button>
        ))}
    </div>
);

const EpisodeListItem: React.FC<{ episode: string; children: React.ReactNode }> = ({ episode, children }) => {
    const episodeNumber = episode.match(/\d+/)?.[0] || '?';
    return (
        <div className="flex items-start space-x-4 py-2">
            <div className="flex-shrink-0 w-10 h-10 bg-gray-100 text-emerald-600 font-bold rounded-full flex items-center justify-center text-sm border-2 border-gray-300">
                {episodeNumber}화
            </div>
            <div className="flex-grow pt-1.5">{children}</div>
        </div>
    );
};

// Drag and Drop Helper
const DragDropZone: React.FC<{
    label?: string;
    subLabel?: string;
    onFileDrop: (file: File) => void;
    children?: React.ReactNode;
    className?: string;
    compact?: boolean;
}> = ({ label, subLabel, onFileDrop, children, className, compact }) => {
    const [isDragOver, setIsDragOver] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragOver(true);
    };
    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragOver(false);
    };
    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragOver(false);
        const file = e.dataTransfer.files[0];
        if (file && file.type.startsWith('image/')) {
            onFileDrop(file);
        }
    };
    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            onFileDrop(file);
            // Reset value so same file can be selected again
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };

    return (
        <div
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            className={`border-2 border-dashed rounded-xl transition-colors cursor-pointer relative overflow-hidden ${
                isDragOver ? 'border-indigo-500 bg-indigo-50' : 'border-gray-300 hover:border-indigo-400 bg-gray-50'
            } ${className} ${compact ? 'p-2' : 'p-6 text-center'}`}
        >
             <input
                type="file"
                ref={fileInputRef}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20"
                accept="image/*"
                onChange={handleChange}
            />
            {children ? (
                children 
            ) : (
                <div className="pointer-events-none z-10 relative">
                    {label && <p className="font-bold text-gray-700 text-sm">{label}</p>}
                    {subLabel && <p className="text-xs text-gray-500 mt-1">{subLabel}</p>}
                </div>
            )}
        </div>
    );
};


export const StoryAnalyzer: React.FC<StoryAnalyzerProps> = ({ onBack }) => {
    const [storyText, setStoryText] = useState('');
    const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [backgroundViewMode, setBackgroundViewMode] = useState('list');
    const [outfitViewMode, setOutfitViewMode] = useState('list');

    // Webtoon Generation State
    const [selectedEpisode, setSelectedEpisode] = useState<string>('');
    const [charRefs, setCharRefs] = useState<CharacterReference[]>([]);
    const [bgRef, setBgRef] = useState<BackgroundReference | null>(null);

    // Options
    const [isColor, setIsColor] = useState<boolean>(true);
    const [hasSpeechBubbles, setHasSpeechBubbles] = useState<boolean>(true);
    // Removed ratio state

    const [isGenerating, setIsGenerating] = useState(false);
    const [generationMode, setGenerationMode] = useState<'single' | 'page'>('single');
    const [generatedPanels, setGeneratedPanels] = useState<{ [cutId: string]: string }>({});
    const [generatedPages, setGeneratedPages] = useState<{ id: number, cuts: string[], image: string }[]>([]);
    const [generationProgress, setGenerationProgress] = useState('');

    // Set default episode when analysis is loaded
    useEffect(() => {
        if (analysis?.charactersByEpisode?.[0]) {
            setSelectedEpisode(analysis.charactersByEpisode[0].episode);
        }
    }, [analysis]);

    const backgroundsByEpisode = useMemo(() => {
        if (!analysis?.backgrounds) return {};
        const grouped: { [key: string]: AnalysisResult['backgrounds'] } = {};
        analysis.backgrounds.forEach(bg => {
            const match = bg.description.match(/(\d+)(?:화)?/);
            const episodeKey = match ? `${match[1]}화` : '기타';
            if (!grouped[episodeKey]) grouped[episodeKey] = [];
            grouped[episodeKey].push(bg);
        });
        return grouped;
    }, [analysis]);

    const outfitsByEpisode = useMemo(() => {
        if (!analysis?.outfits) return {};
        return analysis.outfits.reduce((acc, outfit) => {
            const episodeKey = outfit.episode.match(/\d+/) ? `${outfit.episode.match(/\d+/)[0]}화` : '기타';
            if (!acc[episodeKey]) acc[episodeKey] = [];
            acc[episodeKey].push(outfit);
            return acc;
        }, {} as { [key: string]: AnalysisResult['outfits'] });
    }, [analysis]);

    // Derived state for the currently selected episode's characters
    const currentEpisodeCharacters = useMemo(() => {
        if (!analysis || !selectedEpisode) return [];
        const epData = (analysis.charactersByEpisode as any[]).find((e: any) => e.episode === selectedEpisode);
        if (!epData) return [];
        return epData.characters.split(',').map((s: string) => s.trim()).filter(Boolean);
    }, [analysis, selectedEpisode]);

    // Derived state for filtered recommendations
    const filteredRecommendations = useMemo(() => {
        if (!analysis?.directingRecommendations) return [];
        const recs = analysis.directingRecommendations as any[];
        if (!selectedEpisode) return recs;

        const episodes = analysis.charactersByEpisode as any[] || [];

        // ** FIX **: If only 1 episode is detected in the analysis, we ignore strict prefix matching.
        // This handles cases where the AI simply labeled cuts "1", "2" instead of "1화 1컷".
        if (episodes.length <= 1) {
            return recs;
        }

        // Filter cuts that belong to the selected episode.
        const cleanEp = selectedEpisode.replace(/\s+/g, '');
        return recs.filter((rec: any) => {
             const cleanCut = rec.cut.replace(/\s+/g, '');
             return cleanCut.startsWith(cleanEp);
        });
    }, [analysis, selectedEpisode]);


    const handleAnalyze = useCallback(async () => {
        const inputText = storyText.trim();
        if (!inputText) {
            setError('분석할 스토리 내용이나 Google Docs 링크를 입력해주세요.');
            return;
        }

        setIsLoading(true);
        setError(null);
        setAnalysis(null);

        let contentToAnalyze = inputText;

        const googleDocsRegex = /https:\/\/docs\.google\.com\/document\/d\/([a-zA-Z0-9-_]+)/;
        const match = inputText.match(googleDocsRegex);

        if (match) {
            const docId = match[1];
            // Use the more reliable text export URL instead of scraping the preview page
            const docUrl = `https://docs.google.com/document/d/${docId}/export?format=txt`;
            const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(docUrl)}`;

            try {
                const response = await fetch(proxyUrl);
                if (!response.ok) throw new Error(`CORS proxy failed with status: ${response.status}`);

                // The response is now plain text, no HTML parsing needed
                const extractedText = await response.text();

                if (!extractedText || extractedText.trim().length < 10) {
                     throw new Error('문서 내용을 추출하지 못했습니다. 문서가 비어있거나 공개 상태가 아닐 수 있습니다.');
                }
                contentToAnalyze = extractedText;
            } catch (err) {
                console.error(err);
                setError('오류: 문서를 읽을 수 없습니다. 제공된 Google Docs 링크에 접근할 수 없거나, 문서의 권한이 \'링크가 있는 모든 사용자\'로 설정되지 않았을 수 있습니다.');
                setIsLoading(false);
                return;
            }
        }

        try {
            const result = await analyzeStory(contentToAnalyze);
            setAnalysis(result);
        } catch (err) {
            setError(err instanceof Error ? err.message : '스토리 분석 중 알 수 없는 오류가 발생했습니다.');
        } finally {
            setIsLoading(false);
        }
    }, [storyText]);

    const processFile = (file: File): Promise<{ base64: string, mimeType: string }> => {
        return new Promise((resolve) => {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64String = reader.result as string;
                const base64Data = base64String.split(',')[1];
                resolve({ base64: base64Data, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        });
    };

    const handleSpecificCharDrop = async (name: string, file: File) => {
        const { base64, mimeType } = await processFile(file);
        setCharRefs(prev => {
            // Remove existing ref for this character if any
            const filtered = prev.filter(r => r.name !== name);
            return [...filtered, {
                id: Date.now().toString(),
                name: name,
                imageBase64: base64,
                mimeType: mimeType
            }];
        });
    };

    const handleBgRefDrop = async (file: File) => {
        const { base64, mimeType } = await processFile(file);
        setBgRef({
            id: Date.now().toString(),
            name: "Background Reference",
            imageBase64: base64,
            mimeType: mimeType
        });
    };

    const removeReference = (name: string) => {
        setCharRefs(charRefs.filter(r => r.name !== name));
    };

    const handleGenerateWebtoon = async () => {
        if (!analysis || filteredRecommendations.length === 0) {
            setError('생성할 컷 정보가 없습니다. 회차를 선택하거나 스토리를 분석해주세요.');
            return;
        }

        setIsGenerating(true);
        setGenerationProgress('API 키 확인 중...');
        setError(null);
        setGeneratedPages([]); 

        const options: WebtoonGenerationOptions = {
            isColor,
            hasSpeechBubbles,
        };

        try {
             // API Key Selection Check
            const aiStudio = (window as any).aistudio;
            if (aiStudio) {
                const hasKey = await aiStudio.hasSelectedApiKey();
                if (!hasKey) {
                    await aiStudio.openSelectKey();
                    const checkAgain = await aiStudio.hasSelectedApiKey();
                    if (!checkAgain) throw new Error("API 키가 선택되지 않았습니다.");
                }
            }

            const recommendations = filteredRecommendations;

            if (generationMode === 'single') {
                // --- SINGLE CUT MODE ---
                let completed = 0;
                for (const item of recommendations) {
                    if (generatedPanels[item.cut]) { completed++; continue; }

                    setGenerationProgress(`컷 ${item.cut} 생성 중... (${completed + 1}/${recommendations.length})`);

                    const cutInfo = (analysis.charactersByCut as any[])?.find((c: any) => c.cut === item.cut);
                    const charactersInCut = cutInfo ? cutInfo.characters : "Unknown";

                    try {
                        const image = await generateWebtoonPanel(
                            item.cut,
                            item.recommendation,
                            item.recommendation,
                            charactersInCut,
                            charRefs, 
                            options,
                            bgRef
                        );
                        setGeneratedPanels(prev => ({ ...prev, [item.cut]: image }));
                    } catch (err) {
                        console.error(`Failed to generate cut ${item.cut}`, err);
                    }
                    completed++;
                }
            } else {
                // --- PAGE MODE ---
                const CUTS_PER_PAGE = 4; // Adjust as needed
                const pages = [];
                for (let i = 0; i < recommendations.length; i += CUTS_PER_PAGE) {
                    pages.push(recommendations.slice(i, i + CUTS_PER_PAGE));
                }

                for (let i = 0; i < pages.length; i++) {
                    setGenerationProgress(`페이지 ${i + 1} 생성 중... (${i + 1}/${pages.length})`);

                    const pageCuts = pages[i].map((rec: any) => {
                        const cutInfo = (analysis.charactersByCut as any[])?.find((c: any) => c.cut === rec.cut);
                        return {
                            cut: rec.cut,
                            recommendation: rec.recommendation,
                            characters: cutInfo ? cutInfo.characters : "Unknown"
                        };
                    });

                    try {
                        const image = await generateWebtoonPage(i + 1, pageCuts, charRefs, options, bgRef);
                        setGeneratedPages(prev => [...prev, { 
                            id: i + 1, 
                            cuts: pageCuts.map((p: any) => p.cut), 
                            image 
                        }]);
                    } catch (err) {
                        console.error(`Failed to generate page ${i + 1}`, err);
                    }
                }
            }

            setGenerationProgress('생성이 완료되었습니다.');

        } catch (err) {
             setError(err instanceof Error ? err.message : '웹툰 생성 중 오류가 발생했습니다.');
        } finally {
            setIsGenerating(false);
        }
    };

    return (
        <div className="w-full max-w-4xl mx-auto">
            <div className="mb-6">
                <button
                    onClick={onBack}
                    className="text-emerald-600 hover:text-emerald-800 transition-colors duration-200 flex items-center group text-sm"
                    aria-label="홈으로 돌아가기"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-2 transform group-hover:-translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                    </svg>
                    홈으로 돌아가기
                </button>
            </div>

            {/* Analysis Input Section */}
            <div className="bg-white p-6 md:p-8 rounded-xl shadow-lg border border-gray-200 space-y-6">
                 <div className="text-center">
                    <h2 className="text-3xl font-bold text-gray-900">AI 스토리 분석기</h2>
                    <p className="text-gray-600 mt-2">웹툰 스토리 전체를 붙여넣거나 Google Docs 링크를 입력하면 AI가 등장인물, 배경, 복장, 그리고 각 컷의 연출까지 체계적으로 분석해 드립니다.</p>
                </div>

                <div>
                     <label htmlFor="story-input" className="block text-sm font-medium text-gray-600 mb-2">
                        스토리 전체 내용 또는 Google Docs 링크
                    </label>
                    <textarea
                        id="story-input"
                        rows={10}
                        className="w-full bg-gray-50 border border-gray-300 rounded-md shadow-sm py-2 px-3 text-gray-900 focus:outline-none focus:ring-2 focus:ring-emerald-500 transition placeholder-gray-400"
                        placeholder="구글 문서 링크를 붙여넣으세요 (주의 : 권한을 '링크가 있는 모든 사용자'로 바꿔주세요)"
                        value={storyText}
                        onChange={(e) => setStoryText(e.target.value)}
                    />
                </div>

                <button
                    onClick={handleAnalyze}
                    disabled={isLoading}
                    className="w-full flex justify-center items-center bg-emerald-600 hover:bg-emerald-700 disabled:bg-emerald-500/50 disabled:cursor-not-allowed text-white font-bold py-3 px-4 rounded-md shadow-lg transition-all duration-300 ease-in-out transform hover:scale-105"
                >
                    {isLoading ? '분석 중...' : '스토리 분석하기'}
                </button>
            </div>

            {error && <div className="mt-6"><ErrorMessage message={error} /></div>}

            <div className="mt-12">
                {isLoading && !analysis && <LoadingSpinner />}
                {analysis && (
                    <div className="space-y-6 animate-fade-in">
                        {/* Existing Analysis Results */}
                        <Accordion title="전체 등장인물" defaultOpen={true} copyContent={analysis.allCharacters}>
                           <div className="flex flex-wrap gap-2">
                                {analysis.allCharacters.split(',').map(name => name.trim()).filter(Boolean).map((name, index) => (
                                    <span key={index} className="bg-emerald-100 text-emerald-800 text-sm font-medium px-3 py-1 rounded-full">
                                        {name}
                                    </span>
                                ))}
                            </div>
                        </Accordion>
                        <Accordion title="회차별 등장인물" copyContent={(analysis.charactersByEpisode as any[])?.map(item => `${item.episode}: ${item.characters}`).join('\n') || ''}>
                            <div className="space-y-4">
                                {(analysis.charactersByEpisode as any[])?.map((item, index) => (
                                    <EpisodeListItem key={index} episode={item.episode}>
                                        <p className="font-semibold">{item.characters}</p>
                                    </EpisodeListItem>
                                ))}
                            </div>
                        </Accordion>

                        {analysis.charactersByCut && analysis.charactersByCut.length > 0 && (
                            <Accordion title="컷별 등장인물" copyContent={analysis.charactersByCut.map((item) => `${item.cut}: ${item.characters}`).join('\n') || ''}>
                                <div className="space-y-2 max-h-96 overflow-y-auto pr-2">
                                    {analysis.charactersByCut.map((item, index) => (
                                        <div key={index} className="grid grid-cols-3 gap-4 py-2 border-b border-gray-100 last:border-b-0">
                                            <div className="font-semibold text-gray-700 col-span-1">{item.cut}</div>
                                            <div className="text-gray-800 col-span-2">{item.characters}</div>
                                        </div>
                                    ))}
                                </div>
                            </Accordion>
                        )}

                        {analysis.directingRecommendations && analysis.directingRecommendations.length > 0 && (
                            <Accordion title="컷별 추천 연출" copyContent={analysis.directingRecommendations.map((item) => `${item.cut}: ${item.recommendation}`).join('\n') || ''}>
                                <div className="space-y-2 max-h-96 overflow-y-auto pr-2">
                                    {analysis.directingRecommendations.map((item, index) => (
                                        <div key={index} className="grid grid-cols-3 gap-4 py-3 border-b border-gray-100 last:border-b-0 hover:bg-gray-50 transition-colors rounded p-2">
                                            <div className="font-bold text-indigo-600 col-span-1">{item.cut}</div>
                                            <div className="text-gray-800 col-span-2 whitespace-pre-wrap leading-relaxed">{item.recommendation}</div>
                                        </div>
                                    ))}
                                </div>
                            </Accordion>
                        )}

                        <Accordion title="배경 리스트" copyContent={(analysis.backgrounds as any[])?.map(item => `${item.location}: ${item.description}`).join('\n') || ''}>
                            <div className="mb-4">
                                <ViewToggleButton viewMode={backgroundViewMode} setViewMode={setBackgroundViewMode} modes={[{value: 'list', label: '전체 목록'}, {value: 'episode', label: '회차별 보기'}]} />
                            </div>
                            {backgroundViewMode === 'list' ? (
                                <ul className="list-disc pl-5 space-y-1">
                                    {(analysis.backgrounds as any[])?.map((item, index) => (
                                        <li key={index}><strong>{item.location}:</strong> {item.description}</li>
                                    ))}
                                </ul>
                            ) : (
                                <div className="space-y-4">
                                    {Object.entries(backgroundsByEpisode).map(([episode, bgs]) => (
                                        <EpisodeListItem key={episode} episode={episode}>
                                            <ul className="list-disc pl-5 space-y-1">
                                                {(bgs as any[]).map((bg, i) => <li key={i}>{bg.location}</li>)}
                                            </ul>
                                        </EpisodeListItem>
                                    ))}
                                </div>
                            )}
                        </Accordion>

                        <Accordion title="복장 리스트" copyContent={(analysis.outfits as any[])?.map(item => `${item.character} (${item.episode}): ${item.outfit}`).join('\n') || ''}>
                            <div className="mb-4">
                                <ViewToggleButton viewMode={outfitViewMode} setViewMode={setOutfitViewMode} modes={[{value: 'list', label: '전체 목록'}, {value: 'episode', label: '회차별 보기'}]} />
                            </div>
                            {outfitViewMode === 'list' ? (
                                <ul className="list-disc pl-5 space-y-1">
                                    {(analysis.outfits as any[])?.map((item, index) => (
                                        <li key={index}><strong>{item.character} ({item.episode}):</strong> {item.outfit}</li>
                                    ))}
                                </ul>
                            ) : (
                                 <div className="space-y-4">
                                    {Object.entries(outfitsByEpisode).map(([episode, outfits]) => (
                                        <EpisodeListItem key={episode} episode={episode}>
                                            <ul className="list-disc pl-5 space-y-1">
                                                {(outfits as any[]).map((outfit, i) => <li key={i}><strong>{outfit.character}:</strong> {outfit.outfit}</li>)}
                                            </ul>
                                        </EpisodeListItem>
                                    ))}
                                </div>
                            )}
                        </Accordion>

                        {/* NEW: Webtoon Creation Section */}
                         <div className="mt-8 pt-8 border-t-2 border-gray-100">
                             <h2 className="text-2xl font-bold text-gray-900 mb-6">🎨 AI 컷만화(웹툰) 생성기</h2>
                             <p className="text-gray-600 mb-6">분석된 컷 정보를 바탕으로 고품질 웹툰 이미지를 생성합니다. 캐릭터의 일관성을 위해 이미지 레퍼런스를 등록해보세요.</p>

                             {/* 1. Episode Selection */}
                             <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm mb-6">
                                 <h3 className="font-bold text-gray-800 mb-3">1. 생성할 회차 선택</h3>
                                 <div className="flex flex-wrap gap-2">
                                     {(analysis.charactersByEpisode as any[]).map((ep, index) => (
                                         <button
                                            key={index}
                                            onClick={() => setSelectedEpisode(ep.episode)}
                                            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                                                selectedEpisode === ep.episode 
                                                ? 'bg-indigo-600 text-white shadow-md transform scale-105' 
                                                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                                            }`}
                                         >
                                             {ep.episode}
                                         </button>
                                     ))}
                                 </div>
                                 <p className="text-xs text-gray-500 mt-2">선택한 회차({selectedEpisode})에 해당하는 컷과 등장인물만 아래에 표시됩니다.</p>
                             </div>

                             {/* 2. Character Reference */}
                             <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
