import { GoogleGenAI } from "@google/genai";
import { CharacterReference, BackgroundReference, WebtoonGenerationOptions } from '../types';

// Helper to construct the strict reference prompt
const getReferencePromptFragment = (references: CharacterReference[]): string => {
  if (references.length === 0) return "";

  let prompt = `\n\n### 🛑 CRITICAL INSTRUCTION: ART STYLE & ANATOMY CLONING\n`;
  prompt += `Reference images have been provided at the top of this prompt. \n`;
  prompt += `**YOUR PRIMARY GOAL IS TO MIMIC THE DRAWING STYLE OF THE REFERENCE IMAGES.**\n`;
  prompt += `1. **STYLE MATCHING**: If the reference image is a **STICK FIGURE (Jolla-man)**, you **MUST DRAW A STICK FIGURE**. Do NOT draw a detailed human body.\n`;
  prompt += `2. **LEVEL OF DETAIL**: Do not "improve" or "upgrade" the drawing quality. If the reference is a rough sketch, the output MUST be a rough sketch. If the reference is simple/childish, keep it simple/childish.\n`;
  prompt += `3. **ANATOMY**: Copy the head-to-body ratio and limb thickness exactly. If the character has line arms, draw line arms.\n`;
  prompt += `4. **IGNORE CONTRADICTIONS**: If the text description implies a complex scene but the reference is simple, **prioritize the simple reference style**.\n\n`;

  references.forEach(ref => {
    prompt += `- **${ref.name}**: Look at [Reference for ${ref.name}] above. Clone this character's drawing style and features exactly.\n`;
  });

  return prompt;
};

// 1. Generate Single Panel (Webtoon Cut)
export const generateWebtoonPanel = async (
  cutId: string,
  sceneDescription: string,
  directing: string,
  charactersInCut: string,
  references: CharacterReference[],
  options: WebtoonGenerationOptions,
  backgroundRef?: BackgroundReference | null
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts: any[] = [];

  // --- 1. Push Reference Images FIRST (Crucial for adherence) ---
  references.forEach(ref => {
      parts.push({ text: `[Reference for ${ref.name}]` });
      parts.push({
          inlineData: {
              data: ref.imageBase64,
              mimeType: ref.mimeType
          }
      });
  });

  // Append Background Reference Image
  if (backgroundRef) {
      parts.push({ text: `[Background Reference]` });
      parts.push({
          inlineData: {
              data: backgroundRef.imageBase64,
              mimeType: backgroundRef.mimeType
          }
      });
  }
  // -----------------------------------------------------------

  // DYNAMIC STYLE INSTRUCTION:
  // If references exist, we tell the AI to COPY the style of the references (e.g. stick figure).
  // If no references, we default to "High Quality Webtoon".
  const styleInstruction = references.length > 0
    ? `**VISUAL STYLE**: **MIMIC THE REFERENCE IMAGES EXACTLY.**\n- If references are Stick Figures, DRAW STICK FIGURES.\n- If references are Anime, draw Anime.\n- Color Mode: ${options.isColor ? "Color" : "Black and White"}.`
    : (options.isColor
        ? "**VISUAL STYLE**: High-quality Full Color Webtoon (Manhwa). Vibrant colors. No grayscale."
        : "**VISUAL STYLE**: Black and White Manga/Comics style. High contrast ink lines, screentones. NO COLOR.");

  const bubbleInstruction = options.hasSpeechBubbles
    ? "**SPEECH BALLOONS**: YES. The character IS SPEAKING. Draw a speech bubble."
    : "**SPEECH BALLOONS**: NO. Do not draw any speech bubbles.";

  const bgInstruction = backgroundRef
    ? `**BACKGROUND**: Use the provided [Background Reference] image above. Match the perspective and architecture EXACTLY.`
    : ``;

  // Constructing a very aggressive system prompt
  let promptText = `
    **ROLE**: You are an AI art assistant that mimics the user's drawing style perfectly.
    **TASK**: Draw the scene described below using the **EXACT ART STYLE** of the reference images provided above.

    ### 🛑 ABSOLUTE PRIORITY: REFERENCE STYLE & ANATOMY
    **THE REFERENCE IMAGES ARE THE SUPREME AUTHORITY.**
    - Do not default to "Generic Anime" or "High Quality Illustration" styles.
    - If the reference is a STICK FIGURE, draw a STICK FIGURE.
    - Copy the proportions (head size, body length) from the reference exactly.

    ### SCENE REQUIREMENTS
    1. **CHARACTERS**: ${charactersInCut}
    2. **ACTION**: ${sceneDescription}
    3. **DIRECTION**: ${directing}
    4. **STYLE**: ${styleInstruction}
    5. **BUBBLES**: ${bubbleInstruction}
    ${bgInstruction}
  `;

  // Add Reference Instructions again to reinforce
  promptText += getReferencePromptFragment(references);

  // --- 2. Push Text Prompt LAST ---
  parts.push({ text: promptText });
  // --------------------------------

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: '4:3',
          imageSize: '1K',
        },
      },
    });

    let imageBase64: string | undefined;
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageBase64 = part.inlineData.data;
          break;
        }
      }
    }

    if (imageBase64) return imageBase64;
    throw new Error(`이미지 생성 실패: 모델이 이미지를 반환하지 않았습니다.`);
  } catch (error) {
    console.error(`Error generating webtoon panel for cut ${cutId}:`, error);
    throw error;
  }
};

// 2. Generate Full Page (Manga Page Layout)
export const generateWebtoonPage = async (
  pageId: number,
  cuts: { cut: string; recommendation: string; characters: string }[],
  references: CharacterReference[],
  options: WebtoonGenerationOptions,
  backgroundRef?: BackgroundReference | null
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts: any[] = [];

  // --- 1. Push Reference Images FIRST ---
  references.forEach(ref => {
      parts.push({ text: `[Reference for ${ref.name}]` });
      parts.push({
          inlineData: {
              data: ref.imageBase64,
              mimeType: ref.mimeType
          }
      });
  });

   if (backgroundRef) {
      parts.push({ text: `[Background Reference]` });
      parts.push({
          inlineData: {
              data: backgroundRef.imageBase64,
              mimeType: backgroundRef.mimeType
          }
      });
  }
  // --------------------------------------

  const styleInstruction = references.length > 0
    ? `**VISUAL STYLE**: **MIMIC THE REFERENCE IMAGES EXACTLY.**\n- If references are Stick Figures, DRAW STICK FIGURES.\n- Color Mode: ${options.isColor ? "Color" : "Black and White"}.`
    : (options.isColor
        ? "**VISUAL STYLE**: Full Color Webtoon format."
        : "**VISUAL STYLE**: Black and White Manga format. Screen tones.");

  const bubbleInstruction = options.hasSpeechBubbles
    ? "**SPEECH BALLOONS**: YES. Mandatory."
    : "**SPEECH BALLOONS**: NO. Forbidden.";

   const bgInstruction = backgroundRef
    ? `**BACKGROUND**: Use the provided [Background Reference] image above.`
    : ``;

  let promptText = `
    **ROLE**: Manga Artist / Mimic.
    **TASK**: Draw a Single Page with ${cuts.length} panels.

    ### 🛑 ABSOLUTE PRIORITY: REFERENCE STYLE & ANATOMY
    **THE REFERENCE IMAGES AT THE TOP ARE THE SUPREME AUTHORITY.**
    - If the reference is simple (Stick figure), keep the output simple.
    - Copy character designs and proportions EXACTLY.

    ### SETTINGS
    - **STYLE**: ${styleInstruction}
    ${bubbleInstruction}

    ### PANELS
  `;

  cuts.forEach((cut, index) => {
    promptText += `
    [Panel ${index + 1} (Cut ${cut.cut})]
    - Action: ${cut.recommendation}
    - Characters: ${cut.characters}
    `;
  });

  promptText += `\n${bgInstruction}`;
  promptText += getReferencePromptFragment(references);

  // --- 2. Push Text Prompt LAST ---
  parts.push({ text: promptText });
  // --------------------------------

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: '3:4', // Vertical Page Format
          imageSize: '1K',
        },
      },
    });

    let imageBase64: string | undefined;
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageBase64 = part.inlineData.data;
          break;
        }
      }
    }

    if (imageBase64) return imageBase64;
    throw new Error(`페이지 생성 실패: 모델이 이미지를 반환하지 않았습니다.`);
  } catch (error) {
    console.error(`Error generating webtoon page ${pageId}:`, error);
    throw error;
  }
};

