// Drag and Drop Helper
const DragDropZone: React.FC<{
    label?: string;
    subLabel?: string;
    onFileDrop: (file: File) => void;
    children?: React.ReactNode;
    className?: string;
    compact?: boolean;
}> = ({ label, subLabel, onFileDrop, children, className, compact }) => {
    const [isDragOver, setIsDragOver] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragOver(true);
    };
    const handleDragLeave = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragOver(false);
    };
    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragOver(false);
        const file = e.dataTransfer.files[0];
        if (file && file.type.startsWith('image/')) {
            onFileDrop(file);
        }
    };
    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            onFileDrop(file);
            // Reset value so same file can be selected again
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };

    return (
        <div
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            className={`border-2 border-dashed rounded-xl transition-colors cursor-pointer relative overflow-hidden ${
                isDragOver ? 'border-indigo-500 bg-indigo-50' : 'border-gray-300 hover:border-indigo-400 bg-gray-50'
            } ${className} ${compact ? 'p-2' : 'p-6 text-center'}`}
        >
             <input
                type="file"
                ref={fileInputRef}
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-20"
                accept="image/*"
                onChange={handleChange}
            />
            {children ? (
                children 
            ) : (
                <div className="pointer-events-none z-10 relative">
                    {label && <p className="font-bold text-gray-700 text-sm">{label}</p>}
                    {subLabel && <p className="text-xs text-gray-500 mt-1">{subLabel}</p>}
                </div>
            )}
        </div>
    );
};


export const StoryAnalyzer: React.FC<StoryAnalyzerProps> = ({ onBack }) => {
    const [storyText, setStoryText] = useState('');
    const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [backgroundViewMode, setBackgroundViewMode] = useState('list');
    const [outfitViewMode, setOutfitViewMode] = useState('list');

    // Webtoon Generation State
    const [selectedEpisode, setSelectedEpisode] = useState<string>('');
    const [charRefs, setCharRefs] = useState<CharacterReference[]>([]);
    const [bgRef, setBgRef] = useState<BackgroundReference | null>(null);

    // Options
    const [isColor, setIsColor] = useState<boolean>(true);
    const [hasSpeechBubbles, setHasSpeechBubbles] = useState<boolean>(true);
    const [hasBackground, setHasBackground] = useState<boolean>(true);

    const [isGenerating, setIsGenerating] = useState(false);
    const [generationMode, setGenerationMode] = useState<'single' | 'page'>('single');
    const [generatedPanels, setGeneratedPanels] = useState<{ [cutId: string]: string }>({});
    const [generatedPages, setGeneratedPages] = useState<{ id: number, cuts: string[], image: string }[]>([]);
    const [generationProgress, setGenerationProgress] = useState('');

    // Set default episode when analysis is loaded
    useEffect(() => {
        if (analysis?.charactersByEpisode?.[0]) {
            setSelectedEpisode(analysis.charactersByEpisode[0].episode);
        }
    }, [analysis]);

    const backgroundsByEpisode = useMemo(() => {
        if (!analysis?.backgrounds) return {};
        const grouped: { [key: string]: AnalysisResult['backgrounds'] } = {};
        analysis.backgrounds.forEach(bg => {
            const match = bg.description.match(/(\d+)(?:화)?/);
            const episodeKey = match ? `${match[1]}화` : '기타';
            if (!grouped[episodeKey]) grouped[episodeKey] = [];
            grouped[episodeKey].push(bg);
        });
        return grouped;
    }, [analysis]);

    const outfitsByEpisode = useMemo(() => {
        if (!analysis?.outfits) return {};
        return analysis.outfits.reduce((acc, outfit) => {
            const episodeKey = outfit.episode.match(/\d+/) ? `${outfit.episode.match(/\d+/)[0]}화` : '기타';
            if (!acc[episodeKey]) acc[episodeKey] = [];
            acc[episodeKey].push(outfit);
            return acc;
        }, {} as { [key: string]: AnalysisResult['outfits'] });
    }, [analysis]);

    // Derived state for the currently selected episode's characters
    const currentEpisodeCharacters = useMemo(() => {
        if (!analysis || !selectedEpisode) return [];
        const epData = (analysis.charactersByEpisode as any[]).find((e: any) => e.episode === selectedEpisode);
        if (!epData) return [];
        return epData.characters.split(',').map((s: string) => s.trim()).filter(Boolean);
    }, [analysis, selectedEpisode]);

    // Derived state for filtered recommendations
    const filteredRecommendations = useMemo(() => {
        if (!analysis?.directingRecommendations) return [];
        const recs = analysis.directingRecommendations as any[];
        if (!selectedEpisode) return recs;

        const episodes = analysis.charactersByEpisode as any[] || [];

        // ** FIX **: If only 1 episode is detected in the analysis, we ignore strict prefix matching.
        // This handles cases where the AI simply labeled cuts "1", "2" instead of "1화 1컷".
        if (episodes.length <= 1) {
            return recs;
        }

        // Filter cuts that belong to the selected episode.
        const cleanEp = selectedEpisode.replace(/\s+/g, '');
        return recs.filter((rec: any) => {
             const cleanCut = rec.cut.replace(/\s+/g, '');
             return cleanCut.startsWith(cleanEp);
        });
    }, [analysis, selectedEpisode]);


    const handleAnalyze = useCallback(async () => {
        const inputText = storyText.trim();
        if (!inputText) {
            setError('분석할 스토리 내용이나 Google Docs 링크를 입력해주세요.');
            return;
        }

        setIsLoading(true);
        setError(null);
        setAnalysis(null);

        let contentToAnalyze = inputText;

        const googleDocsRegex = /https:\/\/docs\.google\.com\/document\/d\/([a-zA-Z0-9-_]+)/;
        const match = inputText.match(googleDocsRegex);

        if (match) {
            const docId = match[1];
            // Use the more reliable text export URL instead of scraping the preview page
            const docUrl = `https://docs.google.com/document/d/${docId}/export?format=txt`;
            const proxyUrl = `https://api.allorigins.win/raw?url=${encodeURIComponent(docUrl)}`;

            try {
                const response = await fetch(proxyUrl);
                if (!response.ok) throw new Error(`CORS proxy failed with status: ${response.status}`);

                // The response is now plain text, no HTML parsing needed
                const extractedText = await response.text();

                if (!extractedText || extractedText.trim().length < 10) {
                     throw new Error('문서 내용을 추출하지 못했습니다. 문서가 비어있거나 공개 상태가 아닐 수 있습니다.');
                }
                contentToAnalyze = extractedText;
            } catch (err) {
                console.error(err);
                setError('오류: 문서를 읽을 수 없습니다. 제공된 Google Docs 링크에 접근할 수 없거나, 문서의 권한이 \'링크가 있는 모든 사용자\'로 설정되지 않았을 수 있습니다.');
                setIsLoading(false);
                return;
            }
        }

        try {
            const result = await analyzeStory(contentToAnalyze);
            setAnalysis(result);
        } catch (err) {
            setError(err instanceof Error ? err.message : '스토리 분석 중 알 수 없는 오류가 발생했습니다.');
        } finally {
            setIsLoading(false);
        }
    }, [storyText]);

    const processFile = (file: File): Promise<{ base64: string, mimeType: string }> => {
        return new Promise((resolve) => {
            const reader = new FileReader();
            reader.onloadend = () => {
                const base64String = reader.result as string;
                const base64Data = base64String.split(',')[1];
                resolve({ base64: base64Data, mimeType: file.type });
            };
            reader.readAsDataURL(file);
        });
    };

    const handleSpecificCharDrop = async (name: string, file: File) => {
        const { base64, mimeType } = await processFile(file);
        setCharRefs(prev => {
            // Remove existing ref for this character if any
            const filtered = prev.filter(r => r.name !== name);
            return [...filtered, {
                id: Date.now().toString(),
                name: name,
                imageBase64: base64,
                mimeType: mimeType
            }];
        });
    };

    const handleBgRefDrop = async (file: File) => {
        const { base64, mimeType } = await processFile(file);
        setBgRef({
            id: Date.now().toString(),
            name: "Background Reference",
            imageBase64: base64,
            mimeType: mimeType
        });
    };

    const removeReference = (name: string) => {
        setCharRefs(charRefs.filter(r => r.name !== name));
    };

    const handleGenerateWebtoon = async () => {
        if (!analysis || filteredRecommendations.length === 0) {
            setError('생성할 컷 정보가 없습니다. 회차를 선택하거나 스토리를 분석해주세요.');
            return;
        }

        setIsGenerating(true);
        setGenerationProgress('API 키 확인 중...');
        setError(null);
        setGeneratedPages([]); 

        const options: WebtoonGenerationOptions = {
            isColor,
            hasSpeechBubbles,
            hasBackground,
        };

        try {
             // API Key Selection Check
            const aiStudio = (window as any).aistudio;
            if (aiStudio) {
                const hasKey = await aiStudio.hasSelectedApiKey();
                if (!hasKey) {
                    await aiStudio.openSelectKey();
                    const checkAgain = await aiStudio.hasSelectedApiKey();
                    if (!checkAgain) throw new Error("API 키가 선택되지 않았습니다.");
                }
            }

            const recommendations = filteredRecommendations;

            if (generationMode === 'single') {
                // --- SINGLE CUT MODE ---
                let completed = 0;
                for (const item of recommendations) {
                    if (generatedPanels[item.cut]) { completed++; continue; }

                    setGenerationProgress(`컷 ${item.cut} 생성 중... (${completed + 1}/${recommendations.length})`);

                    const cutInfo = (analysis.charactersByCut as any[])?.find((c: any) => c.cut === item.cut);
                    const charactersInCut = cutInfo ? cutInfo.characters : "Unknown";

                    try {
                        const image = await generateWebtoonPanel(
                            item.cut,
                            item.recommendation,
                            item.recommendation,
                            charactersInCut,
                            charRefs, 
                            options,
                            bgRef
                        );
                        setGeneratedPanels(prev => ({ ...prev, [item.cut]: image }));
                    } catch (err) {
                        console.error(`Failed to generate cut ${item.cut}`, err);
                    }
                    completed++;
                }
            } else {
                // --- PAGE MODE ---
                const CUTS_PER_PAGE = 4; // Adjust as needed
                const pages = [];
                for (let i = 0; i < recommendations.length; i += CUTS_PER_PAGE) {
                    pages.push(recommendations.slice(i, i + CUTS_PER_PAGE));
                }

                for (let i = 0; i < pages.length; i++) {
                    setGenerationProgress(`페이지 ${i + 1} 생성 중... (${i + 1}/${pages.length})`);

                    const pageCuts = pages[i].map((rec: any) => {
                        const cutInfo = (analysis.charactersByCut as any[])?.find((c: any) => c.cut === rec.cut);
                        return {
                            cut: rec.cut,
                            recommendation: rec.recommendation,
                            characters: cutInfo ? cutInfo.characters : "Unknown"
                        };
                    });

                    try {
                        const image = await generateWebtoonPage(i + 1, pageCuts, charRefs, options, bgRef);
                        setGeneratedPages(prev => [...prev, { 
                            id: i + 1, 
                            cuts: pageCuts.map((p: any) => p.cut), 
                            image 
                        }]);
                    } catch (err) {
                        console.error(`Failed to generate page ${i + 1}`, err);
                    }
                }
            }

            setGenerationProgress('생성이 완료되었습니다.');

        } catch (err) {
             setError(err instanceof Error ? err.message : '웹툰 생성 중 오류가 발생했습니다.');
        } finally {
            setIsGenerating(false);
        }
    };

    return (
        <div className="w-full max-w-4xl mx-auto">
            <div className="mb-6">
                <button
                    onClick={onBack}
                    className="text-emerald-600 hover:text-emerald-800 transition-colors duration-200 flex items-center group text-sm"
                    aria-label="홈으로 돌아가기"
                >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-2 transform group-hover:-translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
                    </svg>
                    홈으로 돌아가기
                </button>
            </div>

            {/* Analysis Input Section */}
            <div className="bg-white p-6 md:p-8 rounded-xl shadow-lg border border-gray-200 space-y-6">
                 <div className="text-center">
                    <h2 className="text-3xl font-bold text-gray-900">AI 스토리 분석기</h2>
                    <p className="text-gray-600 mt-2">웹툰 스토리 전체를 붙여넣거나 Google Docs 링크를 입력하면 AI가 등장인물, 배경, 복장, 그리고 각 컷의 연출까지 체계적으로 분석해 드립니다.</p>
                </div>

                <div>
                     <label htmlFor="story-input" className="block text-sm font-medium text-gray-600 mb-2">
                        스토리 전체 내용 또는 Google Docs 링크
                    </label>
                    <textarea
                        id="story-input"
                        rows={10}
                        className="w-full bg-gray-50 border border-gray-300 rounded-md shadow-sm py-2 px-3 text-gray-900 focus:outline-none focus:ring-2 focus:ring-emerald-500 transition placeholder-gray-400"
                        placeholder="구글 문서 링크를 붙여넣으세요 (주의 : 권한을 '링크가 있는 모든 사용자'로 바꿔주세요)"
                        value={storyText}
                        onChange={(e) => setStoryText(e.target.value)}
                    />
                </div>

                <button
                    onClick={handleAnalyze}
                    disabled={isLoading}
                    className="w-full flex justify-center items-center bg-emerald-600 hover:bg-emerald-700 disabled:bg-emerald-500/50 disabled:cursor-not-allowed text-white font-bold py-3 px-4 rounded-md shadow-lg transition-all duration-300 ease-in-out transform hover:scale-105"
                >
                    {isLoading ? '분석 중...' : '스토리 분석하기'}
                </button>
            </div>

            {error && <div className="mt-6"><ErrorMessage message={error} /></div>}

            <div className="mt-12">
                {isLoading && !analysis && <LoadingSpinner />}
                {analysis && (
                    <div className="space-y-6 animate-fade-in">
                        {/* Existing Analysis Results */}
                        <Accordion title="전체 등장인물" defaultOpen={true} copyContent={analysis.allCharacters}>
                           <div className="flex flex-wrap gap-2">
                                {analysis.allCharacters.split(',').map(name => name.trim()).filter(Boolean).map((name, index) => (
                                    <span key={index} className="bg-emerald-100 text-emerald-800 text-sm font-medium px-3 py-1 rounded-full">
                                        {name}
                                    </span>
                                ))}
                            </div>
                        </Accordion>
                        <Accordion title="회차별 등장인물" copyContent={(analysis.charactersByEpisode as any[])?.map(item => `${item.episode}: ${item.characters}`).join('\n') || ''}>
                            <div className="space-y-4">
                                {(analysis.charactersByEpisode as any[])?.map((item, index) => (
                                    <EpisodeListItem key={index} episode={item.episode}>
                                        <p className="font-semibold">{item.characters}</p>
                                    </EpisodeListItem>
                                ))}
                            </div>
                        </Accordion>

                        {analysis.charactersByCut && analysis.charactersByCut.length > 0 && (
                            <Accordion title="컷별 등장인물" copyContent={analysis.charactersByCut.map((item) => `${item.cut}: ${item.characters}`).join('\n') || ''}>
                                <div className="space-y-2 max-h-96 overflow-y-auto pr-2">
                                    {analysis.charactersByCut.map((item, index) => (
                                        <div key={index} className="grid grid-cols-3 gap-4 py-2 border-b border-gray-100 last:border-b-0">
                                            <div className="font-semibold text-gray-700 col-span-1">{item.cut}</div>
                                            <div className="text-gray-800 col-span-2">{item.characters}</div>
                                        </div>
                                    ))}
                                </div>
                            </Accordion>
                        )}

                        {analysis.directingRecommendations && analysis.directingRecommendations.length > 0 && (
                            <Accordion title="컷별 추천 연출" copyContent={analysis.directingRecommendations.map((item) => `${item.cut}: ${item.recommendation}`).join('\n') || ''}>
                                <div className="space-y-2 max-h-96 overflow-y-auto pr-2">
                                    {analysis.directingRecommendations.map((item, index) => (
                                        <div key={index} className="grid grid-cols-3 gap-4 py-3 border-b border-gray-100 last:border-b-0 hover:bg-gray-50 transition-colors rounded p-2">
                                            <div className="font-bold text-indigo-600 col-span-1">{item.cut}</div>
                                            <div className="text-gray-800 col-span-2 whitespace-pre-wrap leading-relaxed">{item.recommendation}</div>
                                        </div>
                                    ))}
                                </div>
                            </Accordion>
                        )}

                        <Accordion title="배경 리스트" copyContent={(analysis.backgrounds as any[])?.map(item => `${item.location}: ${item.description}`).join('\n') || ''}>
                            <div className="mb-4">
                                <ViewToggleButton viewMode={backgroundViewMode} setViewMode={setBackgroundViewMode} modes={[{value: 'list', label: '전체 목록'}, {value: 'episode', label: '회차별 보기'}]} />
                            </div>
                            {backgroundViewMode === 'list' ? (
                                <ul className="list-disc pl-5 space-y-1">
                                    {(analysis.backgrounds as any[])?.map((item, index) => (
                                        <li key={index}><strong>{item.location}:</strong> {item.description}</li>
                                    ))}
                                </ul>
                            ) : (
                                <div className="space-y-4">
                                    {Object.entries(backgroundsByEpisode).map(([episode, bgs]) => (
                                        <EpisodeListItem key={episode} episode={episode}>
                                            <ul className="list-disc pl-5 space-y-1">
                                                {(bgs as any[]).map((bg, i) => <li key={i}>{bg.location}</li>)}
                                            </ul>
                                        </EpisodeListItem>
                                    ))}
                                </div>
                            )}
                        </Accordion>

                        <Accordion title="복장 리스트" copyContent={(analysis.outfits as any[])?.map(item => `${item.character} (${item.episode}): ${item.outfit}`).join('\n') || ''}>
                            <div className="mb-4">
                                <ViewToggleButton viewMode={outfitViewMode} setViewMode={setOutfitViewMode} modes={[{value: 'list', label: '전체 목록'}, {value: 'episode', label: '회차별 보기'}]} />
                            </div>
                            {outfitViewMode === 'list' ? (
                                <ul className="list-disc pl-5 space-y-1">
                                    {(analysis.outfits as any[])?.map((item, index) => (
                                        <li key={index}><strong>{item.character} ({item.episode}):</strong> {item.outfit}</li>
                                    ))}
                                </ul>
                            ) : (
                                 <div className="space-y-4">
                                    {Object.entries(outfitsByEpisode).map(([episode, outfits]) => (
                                        <EpisodeListItem key={episode} episode={episode}>
                                            <ul className="list-disc pl-5 space-y-1">
                                                {(outfits as any[]).map((outfit, i) => <li key={i}><strong>{outfit.character}:</strong> {outfit.outfit}</li>)}
                                            </ul>
                                        </EpisodeListItem>
                                    ))}
                                </div>
                            )}
                        </Accordion>

                        {/* NEW: Webtoon Creation Section */}
                         <div className="mt-8 pt-8 border-t-2 border-gray-100">
                             <h2 className="text-2xl font-bold text-gray-900 mb-6">🎨 AI 컷만화(웹툰) 생성기</h2>
                             <p className="text-gray-600 mb-6">분석된 컷 정보를 바탕으로 고품질 웹툰 이미지를 생성합니다. 캐릭터의 일관성을 위해 이미지 레퍼런스를 등록해보세요.</p>

                             {/* 1. Episode Selection */}
                             <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm mb-6">
                                 <h3 className="font-bold text-gray-800 mb-3">1. 생성할 회차 선택</h3>
                                 <div className="flex flex-wrap gap-2">
                                     {(analysis.charactersByEpisode as any[]).map((ep, index) => (
                                         <button
                                            key={index}
                                            onClick={() => setSelectedEpisode(ep.episode)}
                                            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${
                                                selectedEpisode === ep.episode 
                                                ? 'bg-indigo-600 text-white shadow-md transform scale-105' 
                                                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                                            }`}
                                         >
                                             {ep.episode}
                                         </button>
                                     ))}
                                 </div>
                                 <p className="text-xs text-gray-500 mt-2">선택한 회차({selectedEpisode})에 해당하는 컷과 등장인물만 아래에 표시됩니다.</p>
                             </div>

                             {/* 2. Character Reference */}
                             <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-8">
                                 <div className="bg-gray-50 p-6 rounded-xl border border-gray-200">
                                     <h3 className="font-bold text-gray-800 mb-4">2. 캐릭터 레퍼런스 ({selectedEpisode})</h3>
                                     <p className="text-sm text-gray-600 mb-4">해당 회차에 등장하는 인물들입니다. 이미지를 드래그하여 등록하세요.</p>

                                     <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 max-h-96 overflow-y-auto pr-1">
                                         {currentEpisodeCharacters.map(charName => {
                                             const existingRef = charRefs.find(r => r.name === charName);
                                             return (
                                                 <div key={charName} className="flex flex-col">
                                                     <div className="font-bold text-xs text-gray-700 mb-1 truncate" title={charName}>{charName}</div>
                                                     <DragDropZone 
                                                        onFileDrop={(file) => handleSpecificCharDrop(charName, file)} 
                                                        className={`h-32 flex items-center justify-center relative ${existingRef ? 'border-indigo-500 bg-white' : ''}`}
                                                        compact={true}
                                                     >
                                                         {existingRef ? (
                                                             <div className="relative w-full h-full">
                                                                <img 
                                                                    src={`data:${existingRef.mimeType};base64,${existingRef.imageBase64}`} 
                                                                    className="w-full h-full object-cover rounded-lg"
                                                                    alt={charName}
                                                                />
                                                                <button 
                                                                    onClick={(e) => { e.stopPropagation(); removeReference(charName); }}
                                                                    className="absolute top-1 right-1 bg-red-500 text-white rounded-full w-5 h-5 flex items-center justify-center text-xs shadow-md hover:bg-red-600"
                                                                >
                                                                    ×
                                                                </button>
                                                             </div>
                                                         ) : (
                                                             <div className="text-center">
                                                                 <span className="text-2xl text-gray-300">+</span>
                                                                 <p className="text-[10px] text-gray-400">이미지 놓기</p>
                                                             </div>
                                                         )}
                                                     </DragDropZone>
                                                 </div>
                                             );
                                         })}
                                         {currentEpisodeCharacters.length === 0 && (
                                             <div className="col-span-full text-center text-gray-500 text-sm py-4">
                                                 등장인물 정보가 없습니다.
                                             </div>
                                         )}
                                     </div>
                                 </div>

                                 {/* Background Reference */}
                                 <div className="bg-gray-50 p-6 rounded-xl border border-gray-200">
                                     <h3 className="font-bold text-gray-800 mb-4">3. 배경 레퍼런스 (선택)</h3>
                                     <div className="mb-4">
                                        <DragDropZone label="배경 이미지 드래그 & 드롭" subLabel="클릭하여 파일 선택" onFileDrop={handleBgRefDrop}>
                                            {bgRef && (
                                                <div className="absolute inset-0 bg-white/90 flex flex-col items-center justify-center rounded-xl p-2 z-10">
                                                    <img src={`data:${bgRef.mimeType};base64,${bgRef.imageBase64}`} className="h-16 w-auto object-cover rounded mb-2 shadow" alt="bg-ref" />
                                                    <p className="text-xs text-green-600 font-bold">배경 등록 완료!</p>
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); setBgRef(null); }}
                                                        className="mt-2 text-xs text-red-500 underline"
                                                    >
                                                        삭제
                                                    </button>
                                                </div>
                                            )}
                                        </DragDropZone>
                                     </div>
                                 </div>
                             </div>

                            {/* Style Options */}
                            <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm mb-6 space-y-4">
                                <h3 className="font-bold text-gray-800">4. 생성 옵션</h3>
                                <div className="flex flex-col gap-6">
                                    <div className="flex flex-col md:flex-row gap-6">
                                        <div className="flex items-center space-x-3">
                                            <span className="text-sm font-medium text-gray-700">스타일:</span>
                                            <div className="flex bg-gray-100 rounded-lg p-1">
                                                <button onClick={() => setIsColor(true)} className={`px-3 py-1 text-sm rounded-md transition ${isColor ? 'bg-white shadow text-indigo-600 font-bold' : 'text-gray-500'}`}>컬러 (웹툰)</button>
                                                <button onClick={() => setIsColor(false)} className={`px-3 py-1 text-sm rounded-md transition ${!isColor ? 'bg-white shadow text-gray-800 font-bold' : 'text-gray-500'}`}>흑백 (만화)</button>
                                            </div>
                                        </div>
                                        <div className="flex items-center space-x-3">
                                            <span className="text-sm font-medium text-gray-700">말풍선:</span>
                                            <div className="flex bg-gray-100 rounded-lg p-1">
                                                <button onClick={() => setHasSpeechBubbles(true)} className={`px-3 py-1 text-sm rounded-md transition ${hasSpeechBubbles ? 'bg-white shadow text-indigo-600 font-bold' : 'text-gray-500'}`}>포함</button>
                                                <button onClick={() => setHasSpeechBubbles(false)} className={`px-3 py-1 text-sm rounded-md transition ${!hasSpeechBubbles ? 'bg-white shadow text-gray-800 font-bold' : 'text-gray-500'}`}>제외 (그림만)</button>
                                            </div>
                                        </div>
                                         <div className="flex items-center space-x-3">
                                            <span className="text-sm font-medium text-gray-700">배경:</span>
                                            <div className="flex bg-gray-100 rounded-lg p-1">
                                                <button onClick={() => setHasBackground(true)} className={`px-3 py-1 text-sm rounded-md transition ${hasBackground ? 'bg-white shadow text-indigo-600 font-bold' : 'text-gray-500'}`}>포함</button>
                                                <button onClick={() => setHasBackground(false)} className={`px-3 py-1 text-sm rounded-md transition ${!hasBackground ? 'bg-white shadow text-gray-800 font-bold' : 'text-gray-500'}`}>흰색 (없음)</button>
                                            </div>
                                        </div>
                                    </div>
                                    {/* Ratio selector removed to enforce reference image proportions */}
                                </div>
                            </div>

                            {/* Mode Selection */}
                            <div className="mb-6 flex space-x-4">
                                <button
                                    onClick={() => setGenerationMode('single')}
                                    className={`flex-1 py-3 px-4 rounded-xl border-2 font-bold transition-all ${
                                        generationMode === 'single'
                                        ? 'border-indigo-600 bg-indigo-50 text-indigo-700'
                                        : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-300'
                                    }`}
                                >
                                    🎬 1컷씩 생성 (웹툰형)
                                </button>
                                <button
                                    onClick={() => setGenerationMode('page')}
                                    className={`flex-1 py-3 px-4 rounded-xl border-2 font-bold transition-all ${
                                        generationMode === 'page'
                                        ? 'border-indigo-600 bg-indigo-50 text-indigo-700'
                                        : 'border-gray-200 bg-white text-gray-500 hover:border-indigo-300'
                                    }`}
                                >
                                    📖 페이지 만화 생성 (출판만화형)
                                </button>
                            </div>

                             {/* Error Message near button */}
                             {error && <div className="mb-4"><ErrorMessage message={error} /></div>}

                             {/* Generate Button */}
                             <button
                                type="button"
                                onClick={handleGenerateWebtoon}
                                disabled={isGenerating || filteredRecommendations.length === 0}
                                className={`w-full flex justify-center items-center font-bold py-4 px-4 rounded-xl shadow-lg transition-all transform hover:scale-105 ${
                                    isGenerating || filteredRecommendations.length === 0
                                    ? 'bg-gray-400 cursor-not-allowed text-gray-100' 
                                    : 'bg-indigo-600 hover:bg-indigo-700 text-white'
                                }`}
                            >
                                {isGenerating ? (
                                    <span className="flex items-center">
                                        <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                                        </svg>
                                        {generationProgress}
                                    </span>
                                ) : (
                                    `✨ 컷만화로 만들기 (${filteredRecommendations.length}컷)`
                                )}
                            </button>

                            {filteredRecommendations.length === 0 && analysis && (
                                <p className="text-center text-sm text-red-500 mt-2 bg-red-50 p-2 rounded-lg border border-red-200">
                                    ⚠️ 선택한 회차({selectedEpisode})에 해당하는 컷 정보가 없습니다. <br/>
                                    스토리 분석 결과를 확인하거나 다른 회차를 선택해주세요.
                                </p>
                            )}

                             {/* Gallery - Single Cut Mode */}
                             {generationMode === 'single' && (
                                <div className="mt-8 space-y-12">
                                    {filteredRecommendations.length > 0 ? (
                                        filteredRecommendations.map((item: any, index: number) => {
                                            const img = generatedPanels[item.cut];
                                            return (
                                                <div key={index} className="flex flex-col md:flex-row gap-6 p-6 bg-white rounded-xl shadow-md border border-gray-100">
                                                    <div className="md:w-1/3 space-y-2">
                                                        <div className="inline-block bg-indigo-100 text-indigo-800 px-3 py-1 rounded-full text-sm font-bold mb-2">
                                                            {item.cut}
                                                        </div>
                                                        <p className="text-gray-700 text-sm whitespace-pre-wrap">{item.recommendation}</p>
                                                        {img && (
                                                            <button 
                                                                onClick={() => {
                                                                    const link = document.createElement('a');
                                                                    link.href = `data:image/png;base64,${img}`;
                                                                    link.download = `webtoon_${item.cut}.png`;
                                                                    link.click();
                                                                }}
                                                                className="mt-4 text-xs text-indigo-600 hover:text-indigo-800 font-semibold"
                                                            >
                                                                이미지 다운로드
                                                            </button>
                                                        )}
                                                    </div>
                                                    <div className="md:w-2/3 bg-gray-50 rounded-lg min-h-[300px] flex items-center justify-center border border-gray-200 overflow-hidden">
                                                        {img ? (
                                                            <img 
                                                                src={`data:image/png;base64,${img}`} 
                                                                alt={`Generated panel for ${item.cut}`}
                                                                className="w-full h-auto object-cover"
                                                            />
                                                        ) : (
                                                            <div className="text-gray-400 text-center p-4">
                                                                <p className="text-sm">이미지가 생성되지 않았습니다.</p>
                                                            </div>
                                                        )}
                                                    </div>
                                                </div>
                                            );
                                        })
                                    ) : (
                                        <div className="text-center text-gray-500 py-8">
                                            선택한 회차({selectedEpisode})에 해당하는 컷 정보가 없습니다.
                                        </div>
                                    )}
                                </div>
                             )}

                             {/* Gallery - Page Mode */}
                             {generationMode === 'page' && (
                                <div className="mt-8 space-y-12">
                                    {generatedPages.length > 0 ? generatedPages.map((page, index) => (
                                        <div key={page.id} className="flex flex-col gap-6 p-6 bg-white rounded-xl shadow-md border border-gray-100">
                                            <div className="flex justify-between items-center">
                                                <div className="inline-block bg-indigo-600 text-white px-4 py-2 rounded-lg font-bold">
                                                    Page {page.id}
                                                </div>
                                                <button 
                                                    onClick={() => {
                                                        const link = document.createElement('a');
                                                        link.href = `data:image/png;base64,${page.image}`;
                                                        link.download = `webtoon_page_${page.id}.png`;
                                                        link.click();
                                                    }}
                                                    className="bg-gray-100 hover:bg-gray-200 text-gray-800 px-4 py-2 rounded-lg font-semibold text-sm transition"
                                                >
                                                    이미지 다운로드
                                                </button>
                                            </div>
                                            <div className="flex flex-col md:flex-row gap-6">
                                                <div className="md:w-1/3 bg-gray-50 p-4 rounded-lg border border-gray-200 text-sm text-gray-600 max-h-[600px] overflow-y-auto">
                                                    <h4 className="font-bold mb-2">포함된 컷:</h4>
                                                    <ul className="list-disc pl-5 space-y-1">
                                                        {page.cuts.map(cut => <li key={cut}>{cut}</li>)}
                                                    </ul>
                                                </div>
                                                <div className="md:w-2/3 flex justify-center bg-gray-900 rounded-lg overflow-hidden border border-gray-300">
                                                     <img 
                                                        src={`data:image/png;base64,${page.image}`} 
                                                        alt={`Generated Page ${page.id}`}
                                                        className="w-full h-auto object-contain max-h-[800px]"
                                                    />
                                                </div>
                                            </div>
                                        </div>
                                    )) : (
                                        !isGenerating && <p className="text-center text-gray-500">생성된 페이지가 없습니다. '페이지 만화 생성' 버튼을 눌러주세요.</p>
                                    )}
                                </div>
                             )}

                         </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export interface PlotData {
  plotText: string;
}

export interface EpisodePlot {
  plot: string;
  charCount?: number;
}

export interface StoryInputs {
  genre: string;
  characters: string;
  plot: string;
  episodePlots: EpisodePlot[];
}

export interface StorySegment {
  id: string;
  title: string;
  content: string;
}

export interface AnalysisResult {
  allCharacters: string;
  charactersByEpisode: {
    episode: string;
    characters: string;
  }[];
  charactersByCut: {
    cut: string;
    characters: string;
  }[];
  backgrounds: {
    location: string;
    description: string;
  }[];
  outfits: {
    character: string;
    outfit: string;
    episode: string;
  }[];
  directingRecommendations?: {
    cut: string;
    recommendation: string;
  }[];
}

export interface CharacterReference {
  id: string;
  name: string;
  imageBase64: string;
  mimeType: string;
}

export interface BackgroundReference {
  id: string;
  name: string;
  imageBase64: string;
  mimeType: string;
}

export type PageLayout = 'grid' | 'vertical' | 'dynamic' | 'random';

export interface WebtoonGenerationOptions {
  isColor: boolean;
  hasSpeechBubbles: boolean;
  hasBackground: boolean;
  layout?: PageLayout;
}

import { GoogleGenAI } from "@google/genai";
import { CharacterReference, BackgroundReference, WebtoonGenerationOptions, PageLayout } from '../types';

// Helper to construct the strict reference prompt
const getReferencePromptFragment = (references: CharacterReference[]): string => {
  if (references.length === 0) return "";

  let prompt = `\n\n### 🛑 CRITICAL INSTRUCTION: ART STYLE & ANATOMY CLONING\n`;
  prompt += `Reference images have been provided at the top of this prompt. \n`;
  prompt += `**YOUR PRIMARY GOAL IS TO MIMIC THE DRAWING STYLE OF THE REFERENCE IMAGES.**\n`;
  prompt += `1. **STYLE MATCHING**: If the reference image is a **STICK FIGURE (Jolla-man)**, you **MUST DRAW A STICK FIGURE**. Do NOT draw a detailed human body.\n`;
  prompt += `2. **LEVEL OF DETAIL**: Do not "improve" or "upgrade" the drawing quality. If the reference is a rough sketch, the output MUST be a rough sketch. If the reference is simple/childish, keep it simple/childish.\n`;
  prompt += `3. **ANATOMY**: Copy the head-to-body ratio and limb thickness exactly. If the character has line arms, draw line arms.\n`;
  prompt += `4. **IGNORE CONTRADICTIONS**: If the text description implies a complex scene but the reference is simple, **prioritize the simple reference style**.\n\n`;

  references.forEach(ref => {
    prompt += `- **${ref.name}**: Look at [Reference for ${ref.name}] above. Clone this character's drawing style and features exactly.\n`;
  });

  return prompt;
};

const getLayoutInstruction = (layout: PageLayout = 'random'): string => {
  switch (layout) {
    case 'grid':
      return "**PAGE LAYOUT**: Strict Grid System. 2 columns. Uniform panel sizes. Clean gutters. Stable and calm composition.";
    case 'vertical':
      return "**PAGE LAYOUT**: Webtoon Vertical Scroll style. Panels arranged in a single vertical column. Wide vertical spacing between panels.";
    case 'dynamic':
      return "**PAGE LAYOUT**: DYNAMIC ACTION MANGA. Diagonal panel borders (slanted cuts). Panels overlapping or bleeding to the edge. Speed lines crossing panel borders. High impact composition.";
    case 'random':
    default:
      return "**PAGE LAYOUT**: Standard Manga composition. A balanced mix of wide landscape shots and vertical character close-ups. Organic panel arrangement.";
  }
};

// 1. Generate Single Panel (Webtoon Cut)
export const generateWebtoonPanel = async (
  cutId: string,
  sceneDescription: string,
  directing: string,
  charactersInCut: string,
  references: CharacterReference[],
  options: WebtoonGenerationOptions,
  backgroundRef?: BackgroundReference | null
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts: any[] = [];

  // --- 1. Push Reference Images FIRST (Crucial for adherence) ---
  references.forEach(ref => {
      parts.push({ text: `[Reference for ${ref.name}]` });
      parts.push({
          inlineData: {
              data: ref.imageBase64,
              mimeType: ref.mimeType
          }
      });
  });

  // Append Background Reference Image
  if (backgroundRef && options.hasBackground) {
      parts.push({ text: `[Background Reference]` });
      parts.push({
          inlineData: {
              data: backgroundRef.imageBase64,
              mimeType: backgroundRef.mimeType
          }
      });
  }
  // -----------------------------------------------------------

  // DYNAMIC STYLE INSTRUCTION:
  const styleInstruction = references.length > 0
    ? `**VISUAL STYLE**: **MIMIC THE REFERENCE IMAGES EXACTLY.**\n- If references are Stick Figures, DRAW STICK FIGURES.\n- If references are Anime, draw Anime.\n- Color Mode: ${options.isColor ? "Color" : "Black and White"}.`
    : (options.isColor
        ? "**VISUAL STYLE**: High-quality Full Color Webtoon (Manhwa). Vibrant colors. No grayscale."
        : "**VISUAL STYLE**: Black and White Manga/Comics style. High contrast ink lines, screentones. NO COLOR.");

  const bubbleInstruction = options.hasSpeechBubbles
    ? "**SPEECH BALLOONS**: YES. The character IS SPEAKING. Draw a speech bubble."
    : "**SPEECH BALLOONS**: NO. Do not draw any speech bubbles.";

  let bgInstruction = "";
  if (!options.hasBackground) {
      bgInstruction = "**BACKGROUND**: NONE. The background must be PURE WHITE (Hex #FFFFFF). Do not draw any scenery. Focus entirely on the character.";
  } else if (backgroundRef) {
      bgInstruction = `**BACKGROUND**: Use the provided [Background Reference] image above. Match the perspective and architecture EXACTLY.`;
  } else {
      bgInstruction = `**BACKGROUND**: Draw a detailed background appropriate for the scene description.`;
  }

  // Constructing a very aggressive system prompt
  let promptText = `
    **ROLE**: You are an AI art assistant that mimics the user's drawing style perfectly.
    **TASK**: Draw the scene described below using the **EXACT ART STYLE** of the reference images provided above.

    ### 🛑 ABSOLUTE PRIORITY: REFERENCE STYLE & ANATOMY
    **THE REFERENCE IMAGES ARE THE SUPREME AUTHORITY.**
    - Do not default to "Generic Anime" or "High Quality Illustration" styles.
    - If the reference is a STICK FIGURE, draw a STICK FIGURE.
    - Copy the proportions (head size, body length) from the reference exactly.

    ### SCENE REQUIREMENTS
    1. **CHARACTERS**: ${charactersInCut}
    2. **ACTION**: ${sceneDescription}
    3. **DIRECTION**: ${directing}
    4. **STYLE**: ${styleInstruction}
    5. **BUBBLES**: ${bubbleInstruction}
    6. **BACKGROUND**: ${bgInstruction}
  `;

  // Add Reference Instructions again to reinforce
  promptText += getReferencePromptFragment(references);

  // --- 2. Push Text Prompt LAST ---
  parts.push({ text: promptText });
  // --------------------------------

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: '4:3',
          imageSize: '1K',
        },
      },
    });

    let imageBase64: string | undefined;
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageBase64 = part.inlineData.data;
          break;
        }
      }
    }

    if (imageBase64) return imageBase64;
    throw new Error(`이미지 생성 실패: 모델이 이미지를 반환하지 않았습니다.`);
  } catch (error) {
    console.error(`Error generating webtoon panel for cut ${cutId}:`, error);
    throw error;
  }
};

// 2. Generate Full Page (Manga Page Layout)
export const generateWebtoonPage = async (
  pageId: number,
  cuts: { cut: string; recommendation: string; characters: string }[],
  references: CharacterReference[],
  options: WebtoonGenerationOptions,
  backgroundRef?: BackgroundReference | null
): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const parts: any[] = [];

  // --- 1. Push Reference Images FIRST ---
  references.forEach(ref => {
      parts.push({ text: `[Reference for ${ref.name}]` });
      parts.push({
          inlineData: {
              data: ref.imageBase64,
              mimeType: ref.mimeType
          }
      });
  });

   if (backgroundRef && options.hasBackground) {
      parts.push({ text: `[Background Reference]` });
      parts.push({
          inlineData: {
              data: backgroundRef.imageBase64,
              mimeType: backgroundRef.mimeType
          }
      });
  }
  // --------------------------------------

  const styleInstruction = references.length > 0
    ? `**VISUAL STYLE**: **MIMIC THE REFERENCE IMAGES EXACTLY.**\n- If references are Stick Figures, DRAW STICK FIGURES.\n- Color Mode: ${options.isColor ? "Color" : "Black and White"}.`
    : (options.isColor
        ? "**VISUAL STYLE**: Full Color Webtoon format."
        : "**VISUAL STYLE**: Black and White Manga format. Screen tones.");

  const bubbleInstruction = options.hasSpeechBubbles
    ? "**SPEECH BALLOONS**: YES. Mandatory."
    : "**SPEECH BALLOONS**: NO. Forbidden.";

  let bgInstruction = "";
  if (!options.hasBackground) {
      bgInstruction = "**BACKGROUND**: NONE. PURE WHITE BACKGROUND for all panels.";
  } else if (backgroundRef) {
      bgInstruction = `**BACKGROUND**: Use the provided [Background Reference] image above.`;
  } else {
      bgInstruction = "**BACKGROUND**: Draw appropriate backgrounds for the scenes.";
  }

  const layoutInstruction = getLayoutInstruction(options.layout);

  let promptText = `
    **ROLE**: Manga Artist / Mimic.
    **TASK**: Draw a Single Page with ${cuts.length} panels.

    ### 🛑 ABSOLUTE PRIORITY: REFERENCE STYLE & ANATOMY
    **THE REFERENCE IMAGES AT THE TOP ARE THE SUPREME AUTHORITY.**
    - If the reference is simple (Stick figure), keep the output simple.
    - Copy character designs and proportions EXACTLY.

    ### SETTINGS
    - **STYLE**: ${styleInstruction}
    - **BACKGROUND**: ${bgInstruction}
    - ${layoutInstruction}
    ${bubbleInstruction}

    ### PANELS
  `;

  cuts.forEach((cut, index) => {
    promptText += `
    [Panel ${index + 1} (Cut ${cut.cut})]
    - Action: ${cut.recommendation}
    - Characters: ${cut.characters}
    `;
  });

  promptText += getReferencePromptFragment(references);

  // --- 2. Push Text Prompt LAST ---
  parts.push({ text: promptText });
  // --------------------------------

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: '3:4', // Vertical Page Format
          imageSize: '1K',
        },
      },
    });

    let imageBase64: string | undefined;
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          imageBase64 = part.inlineData.data;
          break;
        }
      }
    }

    if (imageBase64) return imageBase64;
    throw new Error(`페이지 생성 실패: 모델이 이미지를 반환하지 않았습니다.`);
  } catch (error) {
    console.error(`Error generating webtoon page ${pageId}:`, error);
    throw error;
  }
};

