async function callGemini(prompt: string, errorMessage: string): Promise<string> {
    if (!process.env.API_KEY) {
        throw new Error("API Key is not configured. Please set up the API_KEY environment variable.");
    }

    try {
        const response = await ai.models.generateContent({
            model: model,
            contents: prompt,
        });

        const text = response.text;
        if (text) {
            return text.trim();
        } else {
            throw new Error("API did not return any text. The response might have been blocked.");
        }

    } catch (error) {
        console.error(errorMessage, error);
        if (error instanceof Error && error.message.includes('API_KEY')) {
            throw new Error("API Key is invalid or not configured correctly. Please check your environment settings.");
        }
        throw new Error(errorMessage);
    }
}


