import { GoogleGenAI } from "@google/genai";

if (!process.env.API_KEY) {
  throw new Error("API_KEY environment variable not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
const model = 'gemini-2.5-flash';

export async function translateText(text: string, targetLanguage: string): Promise<string> {
  const systemInstruction = `You are an expert translator specializing in creative and technical documents for the film and comics industry. Your task is to translate the provided Korean webtoon script into ${targetLanguage}.

Follow these rules precisely:
1.  Translate the content accurately, preserving the original intent, nuance, and tone.
2.  Maintain the original formatting, including cut numbers (e.g., '1.', '2.'), line breaks, and any markdown like bullet points or bold text.
3.  Translate technical and industry-specific terms correctly. The Korean terms and their meanings are:
    -   '대' (abbreviation for '대사'): Dialogue
    -   '생' (abbreviation for '생각'): Thought
    -   '나' (abbreviation for '나레이션'): Narration
    -   '말풍선': Off-screen Dialogue or OS Dialogue
    -   '효과음': SFX (Sound Effects)
    -   Parenthetical directing notes like '(클로즈업)' should be translated appropriately (e.g., '(Close-up)' in English).
    Translate these Korean terms into their appropriate equivalents in ${targetLanguage}.
4.  Character Name Inference: If the script uses generic terms like '남주' (male lead), '여주' (female lead), '남1', '여1', etc., you must analyze the context of the entire script to infer the character's actual proper name. Once identified, consistently replace the generic term with the correct proper name throughout the translation. For example, if the male lead is identified as '강민우', all instances of '남주' should be translated as 'Kang Minwoo'.
5.  Do not add any extra text, commentary, or explanations. Only provide the direct translation of the input text.`;

  try {
    const response = await ai.models.generateContent({
        model,
        contents: text,
        config: {
            systemInstruction,
        }
    });

    return response.text;
  } catch (error) {
    console.error('Error translating text:', error);
    throw new Error('텍스트를 번역하는 데 실패했습니다.');
  }
}


export async function extractCharactersFromScript(scriptText: string, targetLanguage: string): Promise<string> {
  const systemInstruction = `You are a script analysis AI. Your task is to read the provided webtoon script, which is written in ${targetLanguage}, and identify all the character names mentioned.

