1.  List only the names of the characters.
2.  Return the names as a single, comma-separated string (e.g., "Minwoo Kang, Jihun Han, Yebin Kang").
3.  Do not add any introductory text, labels, explanations, or bullet points. Only output the comma-separated list of names.`;

  try {
    const response = await ai.models.generateContent({
        model,
        contents: scriptText,
        config: {
            systemInstruction,
        }
    });
    return response.text;
  } catch (error)    {
    console.error('Error extracting characters:', error);
    return '등장인물 분석에 실패했습니다.';
  }
}

import React, { useState, useCallback } from 'react';
import { generateStoryboardPages } from '../services/storyboardService';
import { LoadingSpinner } from './LoadingSpinner';
import { ErrorMessage } from './ErrorMessage';

interface StoryboardGeneratorProps {
